-- 03 · Textos (sólo donde razon is null), contexto y saga (sólo donde collection_name is null)
-- PROPUESTA PARA REVISIÓN — NO EJECUTADA. Ruleta "No sé qué ver", ampliación de 500 (2026-10-08).
-- Ninguno de los 500 requiere contexto: requiere_contexto queda en su default (false) y NO se toca
-- ninguna fila existente (excepciones de Harry Potter y Star Wars intactas).
begin;
update roulette_titles rt set razon = v.razon, advertencia = v.advertencia, atencion = v.atencion
from (values
  (82779, 'Cantinflas construye todo desde la confusión de identidad, con esa labia y esos gestos que lo hicieron popular en toda Latinoamérica. La trama de espías y bomba atómica es apenas una excusa para lucir su estilo de improvisación verbal.', 'El costado de espionaje y ciencia ficción es puro pretexto, no esperes que tenga peso real en la trama.', 'fondo'),
  (857729, 'Es parte de la serie documental ''Untold'' de Netflix, centrada en Christy Martin, boxeadora que rompió barreras en un deporte dominado por hombres. El foco está en el lado oscuro de su carrera, no solo en sus logros deportivos.', 'Toca temas de abuso y violencia doméstica de forma directa, no es para mirar relajado.', 'media'),
  (655187, 'Agüero planta la cacería de brujas en un pueblo vasco de pescadores. La lee como un choque entre el control masculino y un grupo de chicas que baila en el bosque. El tramo final, con el baile ritual, cambia el registro de drama histórico a algo más físico y extraño.', 'El juicio del siglo XVII y el dialecto piden algo de paciencia en la primera media hora.', 'alta'),
  (177047, 'Cruza la historia real de la científica que ligó el cáncer de mama a un gen. Del otro lado está Annie Parker, una paciente que intuía esa conexión antes de que se probara en laboratorio. Helen Hunt y Samantha Morton sostienen las dos mitades del relato.', 'La parte de laboratorio y genética puede sentirse densa si no tenés algo de interés en divulgación científica.', 'alta'),
  (254172, 'Sigue a una hija y su padre a lo largo de 25 años, entre la infancia y la adultez. El padre es un novelista que cría sola a su hija mientras lucha contra una enfermedad mental. Apunta directo al golpe emocional, sin disimularlo.', 'Si te incomoda el melodrama explícito y la música subrayando cada escena triste, esta no es para vos.', 'media'),
  (8978, 'Es el remake del clásico de John Carpenter, con Ethan Hawke y Laurence Fishburne enfrentados en una comisaría sitiada. Cambia el tono ochentero original por algo más oscuro y violento. Funciona bien como acción de encierro, sin vueltas.', 'Si viste la original de Carpenter, esta versión pierde parte de la tensión minimalista que la hacía única.', 'media'),
  (2525, 'Huston filma el Génesis a la escala de los grandes épicos bíblicos de Hollywood. Pero se guarda el mejor papel para él mismo: hace de Noé y le pone humor físico a la construcción del arca. El segmento de Sodoma y Gomorra tiene una ambición visual que todavía impresiona, en casi tres horas de metraje.', 'Dura 175 minutos divididos en episodios bastante desiguales entre sí.', 'media'),
  (878361, 'Cubre una vida entera: la pobreza, el boxeo, la religión y el regreso al ring ya grande. Khris Davis se juega físicamente en el personaje y sostiene los tramos más flojos del guion. Funciona para quien quiere la historia completa de Foreman, no un recorte puntual de su carrera.', 'Dura más de dos horas y abarca tantas etapas de su vida que el ritmo se resiente hacia la mitad.', 'media'),
  (2007, 'Nick Nolte y Susan Sarandon hacen de padres que, sin ser médicos, se meten a investigar por su cuenta una enfermedad sin cura conocida. Está basada en un caso real y toma en serio la parte científica de la búsqueda, no solo la emocional. Funciona para quien quiere un drama médico que no apele solo a las lágrimas.', 'Tiene mucha terminología médica y escenas del deterioro físico del nene, es dura para quien tiene hijos chicos.', 'alta'),
  (12165, 'Guillermo Arriaga arma el relato con líneas de tiempo cruzadas, su marca registrada de esa época. Charlize Theron lleva una historia de culpa familiar que se va revelando de a pedazos, sin orden cronológico. Pide paciencia para armar el rompecabezas, pero el drama funciona si te entregás al juego.', 'Si no te gustan los relatos con líneas de tiempo mezcladas, cuesta entender quién es quién al principio.', 'alta'),
  (837, 'Cronenberg en su etapa más visceral: el cuerpo se mezcla con la tecnología hasta que ya no se distingue dónde empieza uno y termina la otra. James Woods hace de un tipo que pierde pie entre la realidad y lo que ve en una señal de TV pirata. Es body horror con ideas detrás, no solo gore.', 'Si buscás una trama prolija y cerrada, esta no te la va a dar.', 'alta'),
  (1013577, 'Es un documental de Chris Smith sobre el padre de Robert Downey Jr. Fue pionero del cine under y la comedia contracultural de los años 60 y 70. Está filmado casi en familia, mientras Downey Sr. estaba enfermo, con un tono bastante íntimo.', 'Si esperás un repaso cronológico de su filmografía, te vas a encontrar con algo mucho más personal y fragmentado.', 'media'),
  (71885, 'Es una película de Disney Channel que traspone ''Noche de Reyes'' de Shakespeare al mundo del motocross. La protagonista se hace pasar por su hermano gemelo para correr en su lugar, y las carreras tienen su espacio real en la trama.', 'Si no te divierte el enredo de mellizos cambiados, buena parte del humor depende de ese truco.', 'media'),
  (8289, 'William Hurt arma a un detective soviético que investiga contra el propio sistema que debería ayudarlo, en plena Guerra Fría. La trama avanza más por la tensión burocrática y política que por la acción. Para quien disfruta el policial de atmósfera antes que el thriller de ritmo rápido.', 'El ritmo es pausado y pide paciencia con las trabas burocráticas del caso.', 'alta'),
  (31658, 'John Sturges ya había filmado el tiroteo en ''Duelo de Titanes''. Acá cuenta la venganza que vino después, cuando Wyatt Earp se corre de la ley que decía representar. James Garner construye un Earp más frío y menos heroico que el de otras versiones del mito.', 'Si esperás la reconstrucción del tiroteo en el O.K. Corral, acá pasa en los primeros minutos y la película se mete en otra cosa.', 'media'),
  (10874, 'Es la versión Muppets de la novela de Stevenson, con Tim Curry haciendo de Long John Silver a pura sobreactuación. La gracia está en el contraste entre la aventura pirata clásica y el humor absurdo de los muñecos. Ideal para ver con chicos sin que los adultos se aburran.', 'Si no tenés cariño previo por los Teleñecos, los chistes meta y las canciones se sienten un relleno.', 'fondo'),
  (38542, 'Arranca como un secuestro planeado al detalle y en minutos empieza a mostrar las fisuras entre los tres personajes encerrados. Gemma Arterton sostiene gran parte de la tensión atada en un departamento, con casi nada de escapatoria. Es un thriller de presupuesto chico que se la juega toda al guión.', 'La primera media hora es cruda y claustrofóbica, sin ningún alivio cómico en el medio.', 'alta'),
  (419680, 'Will Ferrell y Mark Wahlberg suman a sus propios padres al quilombo familiar navideño, secuela directa de Padres por desigual. La diferencia de estilos entre los dos abuelos es el motor de casi todos los chistes.', 'Si no viste la primera, algunos chistes sobre la relación entre los dos padres pierden gracia.', 'fondo'),
  (516329, 'Guillermo del Toro produce y se nota en el tono triste y lento, más cerca del drama social que del terror de sustos. La criatura está basada en el wendigo y aparece poco, el peso está en la pobreza del pueblo. Funciona para quien banca el terror atmosférico antes que el gore.', 'El ritmo es lento y la criatura tarda en aparecer, así que no es terror de sustos rápidos.', 'media'),
  (10294, 'Es un thriller corto y ajustado: la pareja encerrada y la amenaza quedan claras rápido y la tensión no afloja. Kate Beckinsale y Luke Wilson sostienen la película con poco diálogo, a pura reacción física. Buena opción si te gusta el suspenso de espacio cerrado sin elementos sobrenaturales.', 'La premisa del motel con cámaras se explica rápido y después no suma giros nuevos.', 'media'),
  (2061, 'El debut de Nicolas Winding Refn, filmado con cámara en mano y un pulso nervioso que después se volvió su sello. Sigue a un camello de Copenhague durante los días en que todo se le empieza a complicar con su deuda. Es crudo y urgente, sin el estilo visual pulido que Refn desarrolló después.', 'El estrés constante del protagonista no da respiro, así que no es la mejor opción para ver relajado.', 'alta'),
  (2755, 'Jack Nicholson se corre de su registro habitual para hacer un jubilado gris, incómodo con su propia vida pasada. Alexander Payne filma el interior de Estados Unidos sin golpes bajos ni ironía fácil hacia sus personajes. Es una comedia dramática incómoda más que graciosa, de las que se quedan pensando.', 'El tono frío y la falta de resolución cómoda pueden resultar densos si buscás algo más liviano.', 'media'),
  (438396, 'Es un policial español que usa crímenes que recrean primeras apariciones de superhéroes de cómic como excusa para el suspenso, con un guiño directo a los fans del género. Funciona mejor si tenés algo de cultura de cómics, porque buena parte del juego está en reconocer las referencias. El vínculo entre los tres investigadores le suma un costado generacional al caso.', 'Si no tenés idea de cómics clásicos, se te van a escapar varias pistas y guiños del caso.', 'media'),
  (57544, 'Álex de la Iglesia cuenta la historia de un dúo cómico español a lo largo de varias décadas. El ascenso profesional va de la mano con un odio cada vez más genuino entre los dos. Santiago Segura y El Gran Wyoming hacen que esa relación tóxica incomode más de lo que hace reír.', 'El humor cambia de tono varias veces en la película, y el tramo final se pone bastante más oscuro que el arranque.', 'media'),
  (42745, 'Está basada en un cuento de Robert Bloch, el mismo autor de Psicosis, con Peter Cushing y Christopher Lee, que casi no comparten escena. Tiene una secuencia particular filmada desde el punto de vista de la calavera flotando, algo raro para el terror gótico de esos años. Es una producción de Amicus, no de Hammer, con un tono más de objeto maldito que de monstruo clásico.', 'Es más atmósfera y objeto maldito que terror gótico con monstruos, así que el ritmo es lento y sin sustos grandes.', 'media'),
  (553604, 'Liam Neeson hace de un asaltante de bancos retirado que se entrega por amor y termina atrapado entre agentes federales corruptos. Es acción genérica pero prolija, del molde de thriller de venganza que Neeson viene haciendo desde Taken. No busca sorprender, busca cumplir con lo esperado del género sin estirarse de más.', 'Si ya viste varios thrillers de Liam Neeson de los últimos años, esta se siente calcada de las otras.', 'fondo'),
  (20481, 'Clive Barker invierte el esquema típico de terror: los monstruos que viven escondidos en Midian son las víctimas, los cazadores humanos son el peligro real. Es terror de culto de los 90 con maquillaje muy trabajado y una mirada rara en el género. Funciona para quien ya conoce a Barker por Hellraiser y quiere algo distinto.', 'Existió durante años solo una versión recortada por el estudio, en esa edición el tercer acto se siente apurado.', 'media'),
  (6963, 'Gore Verbinski dirige a Nicolas Cage como un hombre del tiempo exitoso en la tele pero un desastre en su vida personal. La gente le tira comida en la calle, literalmente, sin que la cámara pida compasión por él. Es una comedia incómoda y bastante más amarga de lo que promete el afiche.', 'Si buscás una comedia de Nicolas Cage con gags, el humor acá es más incómodo que gracioso.', 'media'),
  (14854, 'Chuck Norris en pleno apogeo ochentoso, con un Texas Ranger solitario que mezcla western con artes marciales. David Carradine como villano le pone un condimento extra de duelo entre estrellas de acción de la época. Es cine de acción directo, sin vueltas, pensado para disfrutar las peleas más que la trama.', 'Si buscás algo más que peleas ochentosas sin pretensiones, la trama del secuestro es bastante simple.', 'fondo'),
  (340666, 'Tom Ford cuenta dos historias en paralelo: la vida vacía de una galerista en Los Ángeles y la novela violenta que le manda su ex pareja. El contraste entre la estética pulida de una parte y la crudeza de la otra es lo que sostiene la película.', 'La violencia de los pasajes ambientados en Texas es mucho más dura que el tono elegante del resto de la película.', 'alta'),
  (8914, 'Es cine de tiburones de los 90 con un gancho científico que dura poco: todo se reduce rápido a sobrevivir en un laboratorio inundado. Tiene un elenco con oficio, con Thomas Jane y Samuel L. Jackson, que le pone seriedad a algo que no la necesita. Funciona para una noche sin pretensiones, con sustos directos y poca vuelta.', 'Los efectos digitales de los tiburones ya se notan de otra época.', 'media'),
  (612, 'Spielberg sigue al equipo del Mossad que persiguió a los responsables de la masacre de los atletas israelíes en Múnich 1972. El peso moral de la venganza, más que la acción, es el eje de la película.', 'Dura casi tres horas con un tono sombrío de punta a punta, sin alivio cómico en el medio.', 'alta'),
  (739990, 'Es una vuelta moderna al cuento de Hansel y Gretel, con un nene fan del terror que tiene que inventar historias de miedo cada noche para sobrevivir en el departamento de una bruja. Funciona bien para chicos que ya están un poco grandes para el terror infantil más inocente. La bruja tiene un costado inesperadamente cómico, no es solo amenaza.', 'Si el chico que mira es muy sensible al terror, algunas escenas con la bruja asustan en serio.', 'media'),
  (21242, 'Burt Lancaster hace de un sheriff méxico-americano al que subestiman por su acento y su edad, hasta que decide cobrarse la humillación. Es un western que se toma su tiempo para mostrar cómo un hombre común se vuelve peligroso.', 'El primer tramo es bastante pausado antes de que arranque la cacería que le da nombre a la película.', 'media'),
  (932430, 'Es una comedia romántica adolescente de fórmula, con la estudiosa que quiere entrar a Harvard pactando con el chico popular para llegar al baile. Cumple todos los clichés del género sin intentar subvertirlos.', 'Si ya viste muchas comedias de baile de graduación, no te va a sorprender ningún giro.', 'fondo'),
  (8223, 'Almodóvar junta en una sola casa a una maquilladora optimista, un fotógrafo obsesionado con la muerte y una conductora de reality despiadada. Suma también a un ex actor porno fugado de la cárcel, y deja que todo explote sin aviso. Es de las películas más excesivas de Almodóvar, con un tono que salta de la comedia a la violencia sin avisar.', 'Hay una escena de violencia sexual filmada en clave de humor negro que a muchos les cuesta digerir.', 'alta'),
  (10288, 'Es una comedia de zombies ambientada en un suburbio de los años 50 estilo utópico, con los muertos vivos como mano de obra doméstica domesticada. El humor sale de llevar esa fantasía familiar hasta el absurdo, sin perder un fondo tierno entre el nene y su zombie. Buena opción si te gusta la comedia negra con corazón, no el terror puro.', 'Si vas buscando terror de zombies tradicional, te vas a encontrar con una comedia de costumbres disfrazada.', 'media'),
  (290864, 'Donnie Yen coreografía sus propias peleas contra un asesino que va matando a los mejores exponentes de distintos estilos marciales en Hong Kong. Cada duelo está pensado como homenaje a una disciplina distinta dentro del kung fu. Funciona para quien busca coreografía de artes marciales por sobre trama policial.', 'La trama policial alrededor de las peleas es bastante floja, está ahí solo para conectar un combate con el siguiente.', 'media'),
  (616747, 'Es la versión con más presupuesto de la atracción de Disney, con un elenco grande que incluye a Owen Wilson y Danny DeVito. Mezcla comedia familiar con terror bien liviano, pensado para ver en grupo. No arriesga nada, pero entretiene sin exigir mucho.', 'Si ya viste la versión de 2003, la estructura de la historia te va a resultar conocida.', 'fondo'),
  (924, 'Zack Snyder debuta en cine con este remake que acelera el ritmo de los zombis clásicos de Romero y lo convierte en acción pura. Un grupo de sobrevivientes se atrinchera en un shopping mientras afuera todo se desmorona.', 'La crítica social que tenía el original de Romero queda bastante de lado a favor de la acción.', 'media'),
  (478860, 'Eva Green juega a una astronauta que tiene que separarse de su hija por un año justo cuando más se necesitan, y la película se detiene más en esa culpa que en el viaje espacial en sí. Es un retrato realista del entrenamiento físico y psicológico previo a una misión, lejos del espectáculo de ciencia ficción. Funciona si te interesa el costado humano del programa espacial europeo.', 'Si buscás una película de astronautas con tensión espacial, acá el drama ocurre casi todo en la Tierra.', 'media'),
  (972614, 'Michael Keaton dirige y protagoniza a un sicario con un diagnóstico de demencia de avance rápido que decide usar el poco tiempo que le queda para acercarse a su hijo. La narración juega con la memoria fallando del propio protagonista mientras la policía se acerca. Es thriller de personaje más que de acción pura.', 'La narración no siempre avisa cuando el tiempo se desordena por la enfermedad del protagonista, pide prestar atención.', 'alta'),
  (8222, 'Almodóvar en pleno exceso melodramático, con Marisa Paredes como diva venida a menos y Victoria Abril como la hija que nunca deja de competir por atención. El policial sirve de excusa para un drama familiar cargado de celos, maternidad y deseo. Si te gusta el culebrón llevado al extremo con estilo visual fuerte, es para vos.', 'Si no te gusta el melodrama exagerado a propósito, la vuelta de tuerca constante cansa.', 'media'),
  (11477, 'De la Iglesia convierte un edificio de vecinos en un escenario de codicia desatada, con un humor negro que no le teme a lo grotesco. Carmen Maura carga la película sola contra un vecindario entero que se vuelve monstruoso por la plata. Es para quien disfruta la comedia negra española sin límites de buen gusto.', 'El humor es bien negro, con escenas de violencia que no esperás de una comedia liviana.', 'media'),
  (843794, 'Es ciencia ficción coreana de Yeon Sang-ho, el director de "Train to Busan", con un dilema más íntimo que espectacular: una hija clonando el cerebro de su madre para la guerra. El trasfondo de guerra civil queda como telón de fondo, el foco está en el laboratorio y en el vínculo filial. Funciona para quien busca ciencia ficción con carga emocional antes que acción pura.', 'Si esperás una película de acción al estilo Netflix convencional, el ritmo es más reflexivo de lo que promete el afiche.', 'media'),
  (326215, 'Le da la vuelta al arca de Noé desde el punto de vista de las especies que quedaron afuera, con un padre y su hijo que se cuelan de polizones. La animación europea tiene un estilo más tosco que las producciones de Hollywood, pero compensa con humor físico. Para ver con chicos chicos, sin buscar sofisticación.', 'La animación es más modesta que la de los estudios grandes y se nota en el detalle de los personajes.', 'fondo'),
  (6077, 'La película arranca como un policial pequeño y de golpe se mete en un círculo clandestino de apuestas con ruleta rusa. Está filmada en blanco y negro seco. La tensión no viene de la acción sino de la espera entre una ronda y otra.', 'Si te incomoda la violencia explícita sin filtro, el tramo del club te va a resultar duro.', 'alta'),
  (18289, 'Esta entrega de la era Heisei le baja el tono pulp a la saga. Mete biotecnología, ética científica y duelo paterno entre las peleas de monstruos. Biollante es un monstruo vegetal, no otro lagarto gigante, así que las coreografías de destrucción cambian bastante.', 'La primera mitad se concentra en la trama científica y tarda en llegar a la acción de kaiju.', 'media'),
  (42661, 'Kirk Douglas y Tony Curtis son hermanos rivales en una épica vikinga de estudio clásico, con escenas de acción que marcaron después a toda una generación de películas sobre vikingos. Es cine de aventuras a la vieja usanza, grandilocuente y sin culpa. Para quien disfruta la aventura clásica más que el rigor histórico.', 'El tratamiento histórico es bastante libre, no busques rigor ahí.', 'media'),
  (152737, 'Es básicamente una obra de teatro filmada, con la familia entera encerrada en una casa destapando rencores viejos. Meryl Streep y Julia Roberts se sacan chispas en escenas largas de mesa, a los gritos. Funciona para quien disfruta el drama familiar verborrágico, no para quien busca algo visual.', 'Si mirás sin atención completa te perdés matices: es puro diálogo cargado, casi teatral.', 'alta'),
  (1059064, 'Matt Damon y Casey Affleck hacen de ladrones torpes cuyo golpe sale mal desde el arranque, y ahí empieza la película en serio. El tono es de comedia de persecución, con la psicóloga metida de rehén improvisada aportando el costado más absurdo. Se disfruta por la química entre los actores más que por la originalidad del robo.', 'Si buscás un policial serio, esta se inclina más hacia la comedia que hacia el suspenso real.', 'media'),
  (9716, 'Es el musical de Woody Allen, con actores no cantantes cantando a propósito, sin pulir las voces. Sigue a una familia neoyorquina rica saltando de problema amoroso en problema amoroso, sin un hilo central fuerte. Gusta más a quien ya es fan de Allen que a quien busca un musical tradicional.', 'Las voces no están afinadas a propósito, así que si esperás números musicales prolijos te va a chocar.', 'media'),
  (6961, 'Es una comedia romántica de manual: ella contrata un acompañante para no llegar sola a la boda de su hermana. Dermot Mulroney hace del gigoló con más onda que vergüenza. No inventa nada nuevo, pero cumple lo que promete.', 'La trama es previsible desde el primer minuto, así que no esperes sorpresas en el camino.', 'fondo'),
  (82775, 'Es cine mexicano clásico con Cantinflas en su estilo de siempre: verborragia, enredos y gags físicos bajo la carpa de un circo. Pensada para quien quiere ver al cómico en su salsa, no un guion sofisticado.', 'Si no te cierra el humor verborrágico de Cantinflas, la película se hace larga.', 'fondo'),
  (1051891, 'June Squibb protagoniza a los 93 años una comedia de acción que parodia las películas de venganza, con un scooter eléctrico en vez de autos o armas. La gracia está en ver el género de acción filtrado por la lógica y el cuerpo de una persona mayor real. Es tierna sin caer en la condescendencia hacia los personajes viejos.', 'Si esperás acción real con riesgo físico, el humor acá viene justamente de la falta de eso.', 'fondo'),
  (10249, 'Es una aventura de aire pulp noventero, con Disney recreando la estética de los seriales de los años treinta. Timothy Dalton se divierte como villano nazi encubierto, con más carisma que el héroe principal. Funciona para quien disfruta el cine de aventuras clásico sin ironía.', 'El protagonista es bastante menos carismático que los villanos y secundarios que lo rodean.', 'media'),
  (2001, 'James Gray filma Nueva York de fines de los 80 con una densidad moral poco habitual en el policial de acción. Joaquin Phoenix hace de la lealtad familiar un problema sin solución fácil, no un arco de redención prolijo. La persecución bajo la lluvia es de lo mejor del género en esa década.', 'El ritmo es más lento que el de un policial promedio, prioriza el drama familiar por sobre la acción.', 'media'),
  (558582, 'Kelly Reichardt filma la amistad entre un cocinero y un inmigrante chino que arman un negocio clandestino con leche robada. No hay persecuciones ni tiroteos, el western acá se cuenta desde la economía y el gesto chico. Funciona para quien busca algo alejado del western de acción.', 'El ritmo es muy pausado y hay tramos largos sin diálogo, no tiene la tensión de un western tradicional.', 'media'),
  (30309, 'America Ferrera debuta acá, antes de ''Betty la fea'', en un papel que no romantiza ni la fábrica ni la pobreza de su barrio. La tensión entre lo que Ana quiere para sí misma y lo que su familia espera de ella se siente genuina, sin golpes bajos.', 'Si buscás un arco más liviano, el peso del tema del cuerpo y la autoestima se siente bastante explícito y repetido.', 'media'),
  (537739, 'Comedia romántica basada en la novela de Sophie Kinsella, con la protagonista contándole sus secretos a un desconocido en un avión. Ese desconocido después resulta ser su nuevo jefe, y ahí arranca el enredo. Es liviana y previsible, pensada para no pensar mucho.', 'Si ya leíste la novela de Kinsella o viste el tráiler, no hay vuelta de tuerca que no veas venir.', 'fondo'),
  (1063877, 'Es un thriller de supervivencia que apuesta casi todo a un truco físico: la protagonista no puede moverse ni hablar y tiene que escapar igual. Kelsey Asbille sostiene la película actuando casi solo con los ojos. Funciona si te gusta el suspenso encerrado y de bajo presupuesto, más que el terror con sustos.', 'Si ya viste varias películas de supervivencia encerrada, la mecánica de la parálisis se vuelve previsible a mitad de metraje.', 'media'),
  (19042, 'Es la secuela animada de ''Todos los perros van al cielo'', con Charlie Barkin metido en otra misión para recuperar un objeto robado del cielo. Mantiene los números musicales y el tono de aventura liviana de la primera, con menos peso emocional que aquella. Es para fans de la original o para ver con los más chicos sin pedirles mucho.', 'Le falta la fuerza emocional de la primera película, que tenía otro motor dramático.', 'fondo'),
  (169917, 'Liam Neeson deja un poco el modo acción pura de Taken para un policial más sucio, basado en las novelas de Lawrence Block. Un expolicía sin licencia investiga un secuestro que se conecta con otros crímenes parecidos.', 'El ritmo es más pausado que otras películas de acción de Neeson de esa misma época.', 'media'),
  (639988, 'Park Chan-wook convierte la desesperación por conseguir trabajo en una comedia negra con capas de crimen. Lee Byung-hun compone a un hombre común que cruza límites sin dejar de parecer razonable. Es el director de Oldboy jugando con el humor incómodo en vez del shock.', 'Dura 139 minutos y el tono cambia de comedia a algo más oscuro varias veces, así que pide paciencia.', 'alta'),
  (104, 'La estructura de repetir los mismos veinte minutos con variaciones es el corazón de la película, no solo un truco visual. Tom Tykwer la filma con una energía de videoclip que todavía se siente fresca. Franka Potente corre literalmente toda la película y transmite una urgencia real.', 'Si no te entra el ritmo desde el arranque, ver la misma situación repetirse tres veces puede cansar.', 'alta'),
  (12149, 'Bill Paxton dirige y actúa en una historia de fe y violencia familiar contada desde la confesión de un hermano al FBI. La estructura de flashback dentro de la confesión mantiene la ambigüedad sobre quién dice la verdad. Matthew McConaughey sostiene el relato con una calma que inquieta más que cualquier grito.', 'El ritmo narrativo es pausado, construye de a poco en vez de ir directo al golpe de efecto.', 'alta'),
  (29060, 'Es terror gótico con Vincent Price, basado en un cuento de Maupassant sobre culpa y posesión. Price construye el personaje con esa teatralidad clásica suya, apostando a la atmósfera antes que al sobresalto.', 'Si buscás sustos o efectos de terror, no los vas a encontrar: el foco está en la atmósfera gótica.', 'media'),
  (193, 'Es el pase de posta entre el elenco original y el de La nueva generación, pensado como puente generacional más que como aventura redonda. Kirk y Picard comparten pantalla por primera y única vez, y ese cruce es el atractivo central. Para fans de la saga vale como evento.', 'Si no viste ninguna serie de Star Trek antes, varias referencias y personajes no se van a entender.', 'media'),
  (2757, 'Charlie Kaufman se escribe a sí mismo, con un hermano gemelo inventado, intentando adaptar un libro que no tiene trama. Es una película sobre lo difícil que es escribir una película, filmada por Spike Jonze.', 'La estructura metaliteraria pide estar atento, si te distraés perdés las capas entre realidad y ficción.', 'alta'),
  (1102493, 'Cillian Murphy sostiene casi toda la película con la mirada, sin necesidad de levantar la voz. Es un drama seco sobre la Irlanda católica de los 80, basado en la nouvelle de Claire Keegan. Funciona para quien prefiere el silencio cargado antes que el golpe de efecto.', 'Si no conocés el trasfondo de los conventos-lavadero irlandeses, el peso real de la historia puede no llegarte del todo.', 'media'),
  (30330, 'Reconstruye la interna real de las cadenas de TV por la sucesión de Johnny Carson en el Tonight Show. Kathy Bates interpreta a la agente que maneja la pelea entre Leno y Letterman. Retrata la ambición del mundo del espectáculo, no una comedia liviana.', 'Si no conocés a Leno, Letterman o Carson, buena parte de la gracia de la interna se pierde.', 'alta'),
  (11915, 'Es la última película de la saga del gendarme con Louis de Funès, acá con policías mujeres sumándose al cuartel. El choque generacional entre la vieja guardia y las nuevas reclutas es el motor de los chistes. Sirve para quien ya conoce la saga, no es punto de entrada.', 'Se nota que de Funès ya estaba enfermo durante el rodaje, el ritmo es más lento que en las primeras del gendarme.', 'fondo'),
  (666243, 'Es una precuela animada centrada en Vesemir, el mentor de Geralt en la serie. El estudio coreano Studio Mir le da una textura más violenta que la serie en vivo. Sirve para quien ya conoce el universo y quiere más contexto, no como punto de entrada.', 'Si no viste la serie, varias referencias y personajes no te van a decir nada.', 'media'),
  (10490, 'Es un falso documental sobre un concurso de belleza de pueblo que se va poniendo cada vez más oscuro y ridículo a medida que las candidatas empiezan a tener ''accidentes''. El humor es negro y filoso, bastante anterior a la ola de mockumentaries que vino después. Kirsten Dunst y Denise Richards se divierten claramente con los personajes.', 'Si te incomoda el humor negro sobre muertes absurdas, esta comedia se pasa de la raya varias veces.', 'media'),
  (10337, 'Warren Beatty construye a Bugsy Siegel como un gángster seducido por Hollywood y por la fantasía de inventar Las Vegas de la nada. El drama se mueve más por la obsesión y el glamour que por la violencia explícita del género. Para quien le interesa el origen del negocio del juego en Nevada contado como tragedia personal.', 'Dura 135 minutos y el tramo final, sostenido solo en la obsesión de Bugsy, se hace lento.', 'media'),
  (1261924, 'Es un documental true crime de Netflix sobre un caso real que generó mucho ruido, armado con entrevistas y material de archivo policial. Funciona para quien sigue el género, con el gancho morboso típico del true crime de la plataforma.', 'Si seguiste el caso en su momento, el documental no suma mucho más de lo que ya salió en la prensa.', 'media'),
  (913673, 'Casi toda la película pasa en una sala de entrevista entre un psiquiatra forense y un condenado a muerte que asegura ser un demonio. El formato es de diálogo encerrado, al estilo de una obra de teatro filmada. Tiene una mirada religiosa bien marcada, no es terror ambiguo.', 'El mensaje religioso es bastante directo, puede sentirse como un sermón para quien no comparte esa mirada.', 'alta'),
  (407447, 'La película sigue al pie de la letra la lógica de cuento picaresco de la novela. Es un viaje imposible que lo lleva de un mueble sueco a una pista de baile romana, sin pedir demasiada lógica interna. Dhanush sostiene el tono liviano incluso cuando la trama toca situaciones duras de migrantes.', 'El tono liviano choca con los pasajes sobre migrantes, resueltos más rápido de lo que el tema pediría.', 'media'),
  (639721, 'Es una secuela de bajo perfil pensada para completar el combo con la primera, sin mucho riesgo creativo. El formato road trip le da estructura episódica, cada parada es casi un sketch separado. Sirve para ver con chicos que ya conocen a la familia.', 'El chiste del humor negro de los Addams se repite de manera parecida a la primera entrega.', 'fondo'),
  (8512, 'Denzel Washington lleva el policial negro clásico al Los Ángeles afroamericano de posguerra, un ángulo que el género rara vez mostraba. Easy Rawlins no es un detective de manual: entra al caso por necesidad de plata, no por vocación. Para quien le gusta el noir con atmósfera de jazz y tensión racial de fondo.', 'Si mirás distraído, la maraña de personajes y motivos del caso se pierde rápido.', 'alta'),
  (256835, 'Es un especial corto hecho para televisión, pensado como puente entre las películas grandes de la saga. Trixie el triceratops tiene su momento central, algo raro en el elenco habitual de Woody y Buzz. Dura apenas veinte minutos, así que no busques la profundidad de las películas grandes.', 'Dura solo 22 minutos, así que la historia queda chica si esperás algo del largo de las películas.', 'fondo'),
  (766798, 'Almodóvar cruza el melodrama de maternidad con la memoria histórica española, dos tramas que al principio parecen no tener nada que ver. Penélope Cruz interpreta a una mujer que no duda de sus decisiones de maternidad. Es más política de lo que el afiche sugiere.', 'Si fuiste buscando solo el drama materno, la subtrama sobre la guerra civil española te va a tomar por sorpresa.', 'alta'),
  (9395, 'El debut de Steven Seagal como protagonista, con el estilo marcial directo que definiría el resto de su carrera. Mezcla policial callejero con conspiración de la CIA, algo más ambicioso que sus películas posteriores. Es ochentosa en el mejor sentido: seca, violenta, sin relleno.', 'Si esperás algo de sutileza actoral, ni esta ni el resto de películas de Seagal te la van a dar.', 'media'),
  (9473, 'Es South Park llevado al musical, con canciones que se ríen de la censura y el pánico moral de los padres. Los chicos terminan metidos en una guerra entre países por culpa de una película que no debían ver.', 'El humor es deliberadamente grosero y políticamente incorrecto, si la serie no te cierra, la película tampoco.', 'media'),
  (9667, 'Adrien Brody carga la película con una angustia física que se siente real, no actuada. Mezcla drama bélico con ciencia ficción psicológica de una manera rara, más cercana al cine independiente que al thriller convencional. Si te gustan las historias de identidad fragmentada, pega en ese lugar.', 'La estructura temporal confunde a propósito en el primer tramo, así que cuesta entrar si mirás distraído.', 'alta'),
  (88431, 'Es un western dirigido por Michael Curtiz, el mismo de Casablanca, con Alan Ladd actuando junto a su hijo real David Ladd. Tiene menos tiros que el western típico de la época y más drama familiar centrado en la relación padre e hijo.', 'Si esperás acción típica de western, acá el conflicto es más íntimo y pausado.', 'media'),
  (1439, 'Versión dramática, no musical, de la historia de la institutriz inglesa en la corte de Siam, con Jodie Foster y Chow Yun-fat. Pone el acento en el choque cultural y político, más que en el romance entre los dos. Está basada en hechos reales, con bastante adorno de guion.', 'Dura 147 minutos y el ritmo cortesano del primer tramo pide paciencia.', 'media'),
  (11329, 'John Grisham otra vez con un juicio como excusa para mostrar manipulación y poder, acá con el negocio de las armas de fondo. Gene Hackman y Dustin Hoffman se miden a distancia, y esa tensión es lo mejor de la película. Para quien disfruta los thrillers legales con trampa incluida.', 'La mecánica de la manipulación del jurado se explica varias veces de más, como para no perder a nadie.', 'media'),
  (432383, 'Es una animación alemana de bajo perfil sobre un chico que esconde alienígenas en su casa. Tiene un tono más cercano al cine europeo chico que al estándar Pixar, sin tanta grandilocuencia.', 'Si tus hijos están acostumbrados a la animación de Pixar o Dreamworks, la factura más modesta se nota.', 'fondo'),
  (972533, 'Es un rescate real que en su momento se hizo conocido, así que la película apuesta a la tensión técnica y a los tiempos exactos, no a la sorpresa. Woody Harrelson y Simu Liu quedan en la superficie, lidiando con una tormenta que vuelve todo más urgente. Es un thriller de minutos contados, no de vueltas de guion.', 'El cruce constante entre la superficie y el fondo del mar corta el ritmo de la tensión en el medio.', 'media'),
  (36464, 'Retrata a Churchill antes de la guerra, en un momento de depresión y ruina económica que la historia oficial suele dejar afuera. El foco está en el matrimonio con Clementine, no en estrategia militar.', 'Si esperás batallas o estrategia de la Segunda Guerra, no las vas a encontrar: es un drama íntimo y doméstico.', 'media'),
  (36465, 'Es la continuación de ''Amenaza de tormenta'' y muestra a Churchill en los diez días de espera por el resultado electoral de 1945. Ya sin el peso de la guerra encima, Albert Finney construye un Churchill íntimo, cansado y bastante menos seguro de sí mismo.', 'Si no viste ''Amenaza de tormenta'', te perdés parte del contexto familiar y político que arrastra esta secuela.', 'alta'),
  (455656, 'Comedia adolescente de fórmula: la chica invisible, la influencer con millones de seguidores, el chico que nunca la vio. No inventa nada nuevo en el género, pero cumple lo que promete sin complicarse. Sirve para una tarde liviana, sin pretensiones.', 'Si ya viste varias comedias adolescentes de Netflix, acá no hay nada que no hayas visto antes.', 'fondo'),
  (615667, 'Es la última actuación de Chadwick Boseman antes de morir. Interpreta a un trompetista con una furia contenida que nunca consigue el lugar que merece. Viola Davis domina cada escena del estudio como Ma Rainey, con una autoridad que no da lugar a dudas.', 'Pasa casi todo en un mismo estudio de grabación, así que si necesitás más movimiento visual puede sentirse encerrada.', 'alta'),
  (421467, 'Ignora todas las secuelas anteriores y retoma el tono serio de la película original del 54, con Godzilla otra vez como amenaza real. El trasfondo de Guerra Fría, con Estados Unidos y la Unión Soviética discutiendo si bombardear Japón, le suma un costado político directo. Para quien prefiere el Godzilla amenazante por sobre el de las peleas coloridas.', 'El tono serio y político desentona con la imagen más amigable de las películas posteriores del personaje.', 'media'),
  (916, 'Steve McQueen construye a Bullitt desde el silencio, no desde la frase ingeniosa. La persecución de autos por las calles de San Francisco marcó el estándar del género y todavía se siente real, sin trucos de cámara. Funciona para quien quiere ver policial seco, sin vueltas sentimentales.', 'Si vas buscando acción todo el tiempo, la primera hora es investigación pausada antes de llegar a la persecución.', 'media'),
  (763215, 'Millie Bobby Brown pasa de princesa de cuento a tener que sobrevivir sola cuando el matrimonio arreglado resulta ser una trampa. Es fantasía de aventuras con una protagonista que se las tiene que ingeniar sin ayuda.', 'La primera mitad es bastante convencional antes de que la película se anime con la supervivencia.', 'media'),
  (3638, 'Es el remake americano de la alemana Bella Martha, con Catherine Zeta-Jones como chef controladora que tiene que criar a su sobrina. La cocina funciona como metáfora fácil del control emocional, nada muy sutil. Sirve como comedia romántica tranquila, sin sorpresas.', 'Dura apenas 76 minutos y se nota, varios conflictos se resuelven demasiado rápido.', 'fondo'),
  (852046, 'Arranca con un plano secuencia larguísimo que mete de lleno en un motín urbano después de la muerte de un pibe. Romain Gavras filma el caos entre tres hermanos priorizando el movimiento de cámara por sobre la pausa. Es más experiencia física que drama reflexivo.', 'El ritmo es agotador de manera deliberada, así que no es la opción si buscás algo para relajarte.', 'alta'),
  (11355, 'Drew Barrymore hace de periodista infiltrada en un secundario, y la comedia funciona por su vergüenza ajena bien actuada. Tiene ese tono de fines de los 90 donde la revancha adolescente se resuelve con humor liviano. Es un antecedente directo, en tono, de comedias como Chicas pesadas.', 'El costado romántico con el profesor envejeció raro visto desde hoy.', 'fondo'),
  (36670, 'Es el regreso de Sean Connery a Bond por fuera de la saga oficial, con más años encima y un tono más irónico sobre sí mismo. No tiene la identidad visual de las Bond de esa época, se nota que es una producción paralela. Para fans de Connery como agente vale como curiosidad, más que como entrega imprescindible.', 'El ritmo es más lento que el de un Bond típico de los 80, con tramos de diálogo que se estiran de más.', 'media'),
  (520023, 'Es una sátira generacional disfrazada de slasher, donde el chiste es lo mal que un grupo de veinteañeros maneja una crisis real. El humor viene de la paranoia y de no saber comunicarse sin filtrar todo por redes sociales. Funciona mejor si te copa el humor incómodo más que el terror puro.', 'Si vas buscando terror clásico con sustos, te vas a encontrar con algo mucho más hablado y menos tenso.', 'media'),
  (352161, 'Pablo Trapero reconstruye el caso del Clan Puccio con una frialdad incómoda, mostrando la vida familiar normal convivir con los secuestros en la misma casa. Guillermo Francella rompe con su imagen de comedia para construir un patriarca sin una gota de culpa visible. Es un pedazo oscuro de la historia argentina reciente, contado como hecho, no como ficción liviana.', 'La frialdad con la que muestra el día a día del clan incomoda más que cualquier escena de violencia explícita.', 'alta'),
  (9686, 'Es un tríptico de tres directores con estilos totalmente distintos: Scorsese con un pintor egocéntrico, Coppola con una nena millonaria y Woody Allen con un mago que hace desaparecer a su madre dominante. La desigualdad entre los tres segmentos es parte de la experiencia: cada uno se siente de una película distinta. El segmento de Allen suele ser el que más se recuerda, por su comedia absurda.', 'El segmento de Coppola es notablemente más flojo que los otros dos y corta el ritmo del conjunto.', 'media'),
  (1151334, 'Samara Weaving vuelve a un pasado del que se había escapado, de conductora de fugas a tener que salvar a un ex en el que nunca pudo confiar. Mezcla acción y comedia con un tono bastante irónico sobre el género de atracos. Funciona para quien disfruta el ritmo acelerado sin tomarse muy en serio a sí mismo.', 'El tono irónico entre comedia y acción no siempre termina de equilibrarse.', 'media'),
  (1992, 'Robert Rodriguez rinde homenaje al cine grindhouse de los setenta con gore exagerado a propósito. Rose McGowan pelea con una pierna de ametralladora en una de las imágenes más recordadas del género.', 'El gore y los daños de imagen simulados son intencionales, no es un error de la copia.', 'media'),
  (10449, 'Encara el alcoholismo sin golpes bajos fáciles: no es solo el personaje de Meg Ryan, es cómo toda la familia construyó su rutina alrededor de la enfermedad. La recuperación que muestra es incómoda, no un arco prolijo de redención. Pensala para un momento tranquilo, no para mirar distraído.', 'La segunda mitad, centrada en terapia familiar, baja bastante el ritmo respecto al arranque.', 'media'),
  (9664, 'Drama bélico sobre los pilotos norteamericanos que volaron para Francia antes de que Estados Unidos entrara a la Primera Guerra. Las escenas de combate aéreo tienen bastante CGI, y se nota más de lo ideal. Es una película de aviones, más que de personajes complejos.', 'Dura 139 minutos y el desarrollo de personajes se siente delgado frente a tanto metraje de vuelo.', 'media'),
  (457955, 'Un hombre se despierta solo en un departamento de París después de una fiesta y descubre que la ciudad ya cayó. Es una película de muertos vivos casi sin diálogo, centrada en la rutina de sobrevivir encerrado. El tono es más melancólico que el de acción típico del género.', 'Si buscás zombis con acción constante, el ritmo contemplativo de la soledad del protagonista te va a aburrir.', 'media'),
  (795514, 'La película se queda en la angustia posterior a una tragedia escolar, no en el hecho en sí. Jenna Ortega lleva el peso de una adolescente que no sabe cómo procesar lo que le pasó. Es un drama íntimo, sin grandes golpes de efecto.', 'El tono introspectivo y lento puede pesar si buscás un drama con más conflicto externo.', 'media'),
  (33379, 'Clive Owen hace de preso que descubre un talento inesperado para la jardinería. La película sigue la misma receta que ''Full Monty'': un grupo castigado por la vida que encuentra dignidad en algo inesperado. Helen Mirren aporta el contraste como experta horticultora.', 'Si ya viste varias películas con esta fórmula de redención grupal británica, el recorrido se siente conocido.', 'media'),
  (424121, 'Gareth Evans cambia las coreografías de pelea de The Raid por un horror folk pausado, con una isla que esconde algo raro desde el principio. La tensión crece despacio y el estallido final es tan físico como sus películas de acción. Para quien banca el horror que se toma su tiempo antes de mostrar las cartas.', 'La primera hora es lenta a propósito, y si esperás la acción de The Raid te vas a desesperar.', 'alta'),
  (836009, 'Está basada en una expedición real a Groenlandia en 1909, con Nikolaj Coster-Waldau como protagonista y también como guionista. El peso está en la supervivencia física, caminando sobre el hielo, más que en el conflicto geopolítico que motiva el viaje. Funciona para quien disfruta historias de resistencia extrema sin heroísmo exagerado.', 'El ritmo es lento en la primera mitad, antes de que arranque la parte de supervivencia.', 'media'),
  (264397, 'Es ciencia ficción mexicana de bajo presupuesto con una idea fuerte: personajes atrapados en espacios que se repiten al infinito durante décadas. Ezban prioriza el concepto por sobre el ritmo, en plan Twilight Zone extendido.', 'Si buscás acción o sustos, la película es más conceptual y lenta que de terror convencional.', 'alta'),
  (11300, 'Jonathan Demme mezcla comedia romántica con thriller criminal, arrancando como un juego de seducción liviano que de golpe se pone oscuro y peligroso. Melanie Griffith y Jeff Daniels tienen una química que sostiene el tono cambiante sin que se sienta forzado. Funciona para quien quiere una película que no se queda quieta en un solo género.', 'Si preferís que la comedia romántica se mantenga liviana todo el metraje, el giro hacia el thriller incomoda.', 'media'),
  (955531, 'Funciona como precuela de Verónica pero se sostiene sola, con un clima de terror pausado más cercano al gótico religioso que al sobresalto fácil. La puesta en escena y el uso de la luz en el convento hacen gran parte del trabajo. Es para quien prefiere la tensión construida de a poco antes que el jump scare.', 'Si buscás sustos frecuentes no los vas a encontrar, el ritmo es lento y contemplativo.', 'alta'),
  (13809, 'Guy Ritchie vuelve a los enredos criminales de Londres con un elenco coral y su estructura típica en capas. Entre mafiosos rusos, contadoras y una estrella de rock drogadicta, todos persiguen la misma plata.', 'Son muchos personajes y tramas cruzadas, si te perdés un diálogo cuesta volver a entrar.', 'alta'),
  (241001, 'Es la primera película animada de Tintín hecha para cine, basada en los álbumes ''Los Siete Orbes de Cristal'' y ''El Templo del Sol''. Respeta a rajatabla el estilo de dibujo clásico de Hergé, algo que se valora si ya conocés las historietas.', 'Si no leíste los álbumes previos, el arranque con la maldición y los arqueólogos dormidos puede costar un poco de entender.', 'media'),
  (178, 'Es un thriller de acción noventoso centrado en bombas, con Jeff Bridges como el experto en desactivación y Tommy Lee Jones como el terrorista del pasado que vuelve. El enfrentamiento es personal, no solo profesional, lo que le da más peso que a otros thrillers de explosivos de la época. Cumple bien si buscás algo de tensión sin pretensiones.', 'El acento irlandés que fuerza Tommy Lee Jones se vuelve distractivo en varias escenas.', 'media'),
  (2067, 'Brian De Palma mete su estilo visual de planos largos y cámara que gira en una historia de ciencia ficción bastante clásica. Es más interesante por cómo está filmada que por lo que cuenta. Para quien disfruta la puesta en escena por sobre el guion.', 'El tramo final se pone más místico que el resto de la película, y no todos conectan con ese cambio de tono.', 'media'),
  (252512, 'Noah Baumbach pone a Ben Stiller frente a una pareja más joven y lo deja mostrar toda su inseguridad sobre el paso del tiempo. Es una comedia incómoda sobre querer seguir siendo relevante, con diálogos filosos. Adam Driver roba varias escenas como el joven que parece tener todo resuelto.', 'La segunda mitad cambia el eje hacia un conflicto profesional que se aleja del tono de comedia del comienzo.', 'media'),
  (826, 'William Holden y Alec Guinness encabezan un drama bélico que es, en el fondo, sobre el orgullo más que sobre la guerra. El coronel Nicholson se aferra a construir bien el puente como forma de dignidad, aunque eso termine ayudando al enemigo. Es cine clásico de gran escala, con un silbido que se volvió icónico.', 'Dura 161 minutos y el primer tramo se toma su tiempo en instalar el conflicto entre oficiales.', 'media'),
  (8967, 'Terrence Malick mezcla la infancia de una familia en los años cincuenta con imágenes del origen del universo. Está más cerca de la poesía visual que de una narración convencional con conflicto y resolución.', 'No tiene una trama tradicional, si necesitás una historia con estructura clara te va a frustrar.', 'alta'),
  (899112, 'David Harbour hace de un Papá Noel borracho y cansado del mundo que termina convertido en máquina de matar mercenarios. Mezcla la estética navideña con la violencia explícita de una película de acción ochentosa, a propósito. Funciona si te gusta el humor negro con sangre de verdad.', 'La violencia es bastante gráfica para algo que se vende como comedia navideña familiar.', 'media'),
  (618416, 'Está basada en una historia real y evita el golpe bajo fácil al mostrar la adaptación de Sam a su nueva vida como un proceso, no un milagro. El pájaro funciona como disparador emocional para toda la familia, no solo para ella. Para quien busca un drama familiar sensible sin golpes bajos forzados.', 'El ritmo es tranquilo y pide paciencia si buscás algo con más tensión narrativa.', 'media'),
  (11338, 'Jeff Goldblum arranca como un insomne sin rumbo y termina arrastrado a una noche entera de quilombos ajenos que no eligió. Landis llena la película de cameos de directores amigos, un juego para cinéfilos más que un chiste central. Funciona para quien disfruta las comedias de una noche loca de los 80.', 'La acumulación de cameos de directores distrae si no los reconocés.', 'media'),
  (11980, 'No tiene nada que ver con la novela de Dan Brown que comparte título en español, acá el tema es una guerra civil entre ángeles. Christopher Walken hace del arcángel Gabriel, bastante lejos del ángel de estampita. Es terror religioso de los 90, para quien busca algo distinto al demonio típico de Hollywood.', 'El título en español genera confusión, muchos la buscan pensando en la de Dan Brown con Tom Hanks.', 'media'),
  (4380, 'Es el remake de una película japonesa, pero acá el eje es Richard Gere descubriendo el baile de salón como escape de una vida cómoda y vacía. Jennifer Lopez queda más como motor de la trama que como protagonista real. Sirve para una noche liviana, sin pretensiones de romance intenso.', 'La relación central promete más química de la que realmente desarrolla en pantalla.', 'fondo'),
  (28894, 'Fritz Lang dirige este western con una canción que vuelve todo el tiempo para ir contando la historia, un recurso poco común en el género. Marlene Dietrich hace de la dueña de un refugio de forajidos llamado Chuck-a-luck, y la película se mete más con su culpa moral que con tiroteos. Se filmó casi todo en estudio, por lo que el paisaje se ve bastante artificial para un western.', 'Se rodó casi entero en estudio, así que el paisaje del Oeste se ve notoriamente artificial comparado con otros westerns.', 'media'),
  (310568, 'La directora lituana Alanté Kavaité ganó el premio a mejor dirección en la sección Un Certain Regard de Cannes por esta película. Usa las acrobacias aéreas como metáfora del deseo de Sangaile de escapar de su vida, más que como un hecho central de la trama. Es cine de clima y sensaciones, con poco diálogo, antes que una historia con muchos hechos.', 'Tiene muy poca trama y avanza por clima y sensaciones: exige paciencia si buscás hechos concretos.', 'media'),
  (864873, 'Es un thriller de terror psicológico de bajo perfil, centrado en sesiones de hipnosis que se van torciendo. Apuesta más a la incomodidad progresiva que a los sustos clásicos. Sirve para una noche de terror que no busca ser gore.', 'Si buscás terror con sustos frecuentes, acá el avance es lento y mental antes que visual.', 'media'),
  (4133, 'Johnny Depp interpreta a George Jung en una biografía que sigue su ascenso como narcotraficante durante los setenta. Más que el delito en sí, le interesa mostrar cómo se le fue de las manos la propia vida.', 'Dura casi dos horas y el tramo final, ya en declive, se siente más lento que el ascenso.', 'media'),
  (3107, 'Toho junta en una sola película a casi todos sus monstruos para enfrentarlos a una invasión alienígena. La isla donde los tienen controlados es la excusa para mostrar a Godzilla, Mothra, Rodan y el resto compartiendo pantalla. Es más espectáculo de monstruos en manada que terror o ciencia ficción seria.', 'Con tantos monstruos en pantalla, cada uno tiene poco tiempo propio.', 'media'),
  (835113, 'Anna Kendrick debuta como directora con esta reconstrucción del momento en que un asesino serial apareció en un programa de citas de los setenta. El eje está en cómo el sistema que rodeaba a Cheryl no vio lo evidente, no en el morbo del caso. Es un true crime que prioriza la incomodidad por sobre el sensacionalismo.', 'Si buscás el morbo típico del true crime sobre asesinos seriales, el foco acá está en otro lado.', 'media'),
  (16428, 'Jamie Foxx convierte su propio despecho en un manual de autoayuda, y la comedia sale de ver sus consejos volverse en su contra. Es una comedia romántica coral típica de mediados de los 2000, con el grupo de amigos como coro de la historia.', 'Si ya viste muchas comedias románticas corales de esa década, la estructura te va a resultar conocida.', 'media'),
  (85550, 'Hong Sang-soo arma una película dentro de otra película. La gracia está en ir descubriendo dónde termina la ficción que mira el protagonista y dónde empieza su propia vida. Es cine coreano de diálogos largos y sobremesas con alcohol, más cerebral que emotivo.', 'Si no conocés el estilo de Hong Sang-soo, la estructura de película-dentro-de-película puede marear al principio.', 'alta'),
  (4191, 'Truffaut le rinde homenaje a Hitchcock con esta historia de venganza en serie. Hasta usa a Bernard Herrmann para la música, el mismo compositor de varias películas del propio Hitchcock. Jeanne Moreau cambia de disfraz y de método con cada víctima, y ahí está el placer de verla armar cada encuentro.', 'Si buscás suspenso sobre a quién va a matar después, la estructura episódica le quita intriga a esa pregunta.', 'media'),
  (814338, 'Emma Corrin y Jack O''Connell sostienen esta versión de la novela de Lawrence centrada en el deseo físico, no en el escándalo de clase. Es una adaptación con escenas explícitas, sin pudor en mostrar la relación entre los dos protagonistas. Funciona para quien busca drama romántico de época con calor, no solo vestuario.', 'Si buscás la crítica de clase de la novela original, acá queda bastante relegada frente al romance.', 'media'),
  (10675, 'Roman Polanski pone a Harrison Ford perdido en un París que no entiende, buscando a su esposa desaparecida. Es un suspenso de paranoia urbana, más cercano al policial europeo que al thriller típico de Hollywood. La tensión viene de la impotencia del idioma y el lugar, no de la acción.', 'El ritmo es más cercano al suspenso europeo que a un thriller de acción con Harrison Ford.', 'media'),
  (9460, 'Jet Li pelea con una coreografía de Yuen Woo-ping que mezcla wire-fu con el género de súper soldados experimentales. Es algo poco común en su filmografía de la época. La trama del ex compañero de armas convertido en amenaza es la excusa para enlazar escenas de acción cada vez más extremas.', 'El doblaje y el montaje de la versión occidental le restan bastante al ritmo original.', 'media'),
  (749004, 'Céline Sciamma cuenta un duelo infantil con una delicadeza enorme, sin un gramo de sentimentalismo forzado. La fantasía que atraviesa la historia nunca se explica del todo, y por eso funciona: deja que la conexión entre las dos nenas hable sola. Dura poco más de una hora, así que no estira nada.', 'Si esperás que la fantasía se resuelva con lógica explicada, la película no te la va a dar.', 'media'),
  (3179, 'Los dos personajes de MTV salen a buscar su televisor robado y terminan en un cruce de país con la CIA de por medio. No se enteran de nada de lo que pasa alrededor, y ese contraste es el chiste central. Mike Judge dirige y pone las voces de los dos.', 'Si no te copó la serie original, el humor bruto de los personajes se agota rápido en formato largo.', 'fondo'),
  (11351, 'The Creeper ataca a un micro lleno de estudiantes de secundaria varados en medio de la nada, en su último día de caza antes de hibernar. Es más acción de terror que la primera, con menos atmósfera y más persecución directa. Funciona si te gusta el monstruo como amenaza física más que como misterio.', 'Pierde parte del clima inquietante de la primera a cambio de más acción y menos tensión lenta.', 'media'),
  (698432, 'Es un drama chileno chico sobre un hombre con una infancia traumática en la música, que ahora se esconde en el campo. La fuerza está en el protagonista, no en la trama, que avanza despacio.', 'Si buscás un ritmo ágil, la primera mitad construye al personaje sin apurarse y puede sentirse estancada.', 'media'),
  (40095, 'Es una comedia policial ochentera con muertos vivos y maquillaje gore práctico, pensada para reírse del absurdo sin tomárselo en serio. Treat Williams y Joe Piscopo hacen de policías en plan parodia, con ritmo de buddy movie clásico.', 'Si esperás terror en serio, el gore ochentero y el humor bobo te van a sacar de clima.', 'media'),
  (10210, 'Esta versión traslada la comedia de Shakespeare a una Italia de bicicletas y vino, con Michelle Pfeiffer y Kevin Kline en los roles centrales. Stanley Tucci como Puck le da un tono travieso que sostiene el enredo de parejas cruzadas por la magia. Es una lectura bastante accesible del texto, pensada para quien nunca leyó la obra.', 'Si ya conocés bien la obra original, esta adaptación no aporta una lectura muy distinta.', 'media'),
  (1931, 'DJ llega de Los Ángeles a una universidad históricamente afroamericana y descubre el stepping, un estilo de baile de fraternidades con raíces muy antiguas. Mezcla esas coreografías tradicionales con movimientos de hip hop, lo que arma la rivalidad central. Funciona para fans de películas de baile tipo Step Up.', 'La trama personal sobre el duelo queda en segundo plano frente a las coreografías.', 'fondo'),
  (11018, 'Michael Cimino filma el choque entre la policía y la mafia china de Chinatown con el mismo tono operístico de El cazador. Mickey Rourke hace de policía obsesivo que cruza límites éticos en su cruzada personal. El guión lo escribió Oliver Stone, lo que se nota en el tono de denuncia social.', 'La película fue señalada en su momento por estereotipar a la comunidad chino-americana, algo que todavía se discute.', 'alta'),
  (11708, 'Es un musical familiar de los años 60, con canciones pegadizas y ese tono entre inventor excéntrico y aventura infantil. El auto volador es la estrella, más que cualquier actuación. Ideal para ver con chicos que todavía disfrutan los musicales clásicos.', 'Dura 140 minutos y el ritmo decae en el tramo del castillo, sobre todo para los más chicos.', 'fondo'),
  (500682, 'Cuenta la cacería de Bonnie and Clyde desde el lado de los cazadores veteranos, no desde la pareja de criminales que todos conocen. Kevin Costner y Woody Harrelson hacen de dos ex Rangers viejos y cansados, lejos del glamour de otras versiones de la historia. Es un western tardío, más sobre el peso de los años que sobre la acción.', 'Si esperás el glamour de Bonnie and Clyde, esta va por otro lado, más gris y cansado.', 'media'),
  (639798, 'Es terror español ambientado en un edificio real de Madrid, con una familia de clase trabajadora como protagonista en vez de la típica casa de ricos embrujada. La época, con la dictadura terminando, le da un trasfondo social que pocas películas de casas encantadas tienen. Funciona bien para quien disfruta el terror con ambientación de época.', 'Si ya viste muchas películas de casas embrujadas, varios recursos de sustos te van a resultar conocidos.', 'media'),
  (24020, 'Es un clásico de Disney Channel de fines de los 90, con el choque entre la cultura del surf y la del snowboard como motor de la historia. Funciona como nostalgia pura para quien creció viendo estas películas de sobremesa. La trama es simple y previsible, pensada para no exigir mucha atención.', 'La rivalidad entre surfistas y snowboarders es bastante esquemática, con el villano reducido a un capricho.', 'fondo'),
  (50717, 'Es aventura familiar clásica de Disney de los años 50, con Davy Crockett y Georgie enfrentando piratas fluviales. El tono es liviano y heroico, pensado para ver en familia sin mayores sobresaltos.', 'El tratamiento de los pueblos originarios es el típico de Hollywood de los años 50, bastante desactualizado.', 'fondo'),
  (529790, 'Es una coproducción franco-andina que mezcla animación con cosmovisión incaica, sobre un pueblo de montaña que enfrenta la llegada de los conquistadores españoles. El protagonista quiere ser chamán justo en el momento en que esa tradición está por desaparecer.', 'Si buscás algo con ritmo más veloz tipo animación comercial, el tono acá es pausado y casi ceremonial.', 'media'),
  (939335, 'Aaron Eckhart lidera un thriller policial de acción directa, que usa la muerte del perro como disparador de una trama más grande. Es cine de género B bien ejecutado, sin ambiciones de prestigio. Para quien busca acción policial sin vueltas.', 'La trama de conspiración se vuelve predecible pasada la primera mitad.', 'media'),
  (5206, 'Von Trier filma esto como un chiste sobre el management corporativo, con la cámara eligiendo sola el encuadre según un algoritmo que él mismo armó. El actor que hace de jefe ficticio se va hundiendo en una mentira que no armó. Es una comedia seca, lejos del Von Trier dramático de otras películas.', 'Si no conocés el experimento de la cámara aleatoria, algunos encuadres te van a parecer simplemente torpes.', 'media'),
  (40996, 'Cantinflas hace lo que mejor sabe hacer: enredar un oficio serio con su verborragia y su aire de pícaro callejero. La trama del secuestro queda en segundo plano frente a sus improvisaciones dentro del cuartel de bomberos.', 'El humor de Cantinflas depende mucho del español mexicano de los años 50, así que algunos juegos de palabras no viajan bien.', 'fondo'),
  (578908, 'Eric André y Lil Rel Howery arman bromas de cámara oculta sobre gente real, no actores pagados, en un viaje por carretera. El humor incomoda a propósito, en la línea de Jackass o Borat. Funciona mejor si te gusta el humor cringe, no el chiste prolijo.', 'El humor depende de la reacción genuina de la gente, así que a mitad de película el gag empieza a repetirse.', 'fondo'),
  (9535, 'Robert De Niro hace de capo mafioso que entra en pánico y termina en terapia con un psiquiatra que no quiere saber nada con el caso. La gracia nace de ver a De Niro parodiar su propia imagen de duro de otras películas. Billy Crystal hace de contrapeso nervioso perfecto para esa dinámica.', 'El chiste central se repite bastante y en el tramo final pierde algo de fuerza.', 'media'),
  (29787, 'Romero se corre del zombie para construir un terror más psicológico, sobre la dependencia y el control del propio cuerpo. El mono como amenaza funciona porque la película lo toma en serio, sin caer en lo ridículo del concepto. Para quien busca terror ochentoso con cabeza, no solo sustos.', 'El concepto del mono asesino suena ridículo al principio y cuesta un poco entrar.', 'media'),
  (34474, 'Marlene Dietrich hizo esta película con el director Josef von Sternberg, con el número musical Hot Voodoo, donde ella aparece disfrazada de gorila antes de cantar. Es de antes del Código Hays, así que se permite ser más directa con una mujer que vuelve al cabaret para salvar a su marido enfermo. Von Sternberg la filma muy estilizada, más atenta a la imagen de Dietrich que al realismo.', 'El guion castiga moralmente cada decisión de Helen, con una mirada bastante dura para los parámetros actuales.', 'media'),
  (55846, 'Jason Statham hace de un policía violento y políticamente incorrecto que persigue a un asesino serial de agentes en Londres. Es un policial duro, de bajo perfil, más cercano al tono sucio de las novelas de Ken Bruen que a una película de acción estándar de Statham. No busca ser elegante, busca ser áspero.', 'Si esperás la acción pulida habitual de Statham, el tono acá es más sucio y a veces confuso.', 'media'),
  (11323, 'Matt Damon hace de un informante corporativo que se cree un agente secreto, y ahí sale la comedia. El desfasaje entre lo que el tipo imagina y lo que realmente pasa es el motor de la película. Es más comedia que thriller corporativo clásico.', 'El protagonista es un narrador poco confiable y la película no avisa cuándo miente, así que pide atención constante.', 'alta'),
  (50456, 'Saoirse Ronan es una adolescente entrenada como asesina por su propio padre, un exagente de la CIA. La música electrónica de Chemical Brothers le da un pulso distinto a las escenas de acción.', 'La acción se mezcla con tramos lentos de corte casi de cuento, no es acción constante.', 'media'),
  (964980, 'Ben Affleck cuenta cómo Nike armó la apuesta por un novato llamado Michael Jordan, pero nunca lo muestra jugar ni hablar en cámara. El centro está en Sonny Vaccaro, interpretado por Matt Damon, y en Deloris Jordan, la madre que negoció los términos. Es un drama de oficina filmado con el ritmo de una película deportiva.', 'Si esperás ver básquet en cancha, no hay casi nada: es todo reuniones y pasillos.', 'media'),
  (33247, 'Gregg Araki filmó esto en plena crisis del sida, con dos protagonistas que deciden no tener ya nada que perder. Es cine queer crudo, filmado con bronca, sin intención de caerle bien a nadie.', 'Si buscás un relato esperanzador sobre la enfermedad, acá la postura es de rabia y nihilismo, no de consuelo.', 'media'),
  (11198, 'Jackie Chan en su veta más payasa, basado en el manga del mismo nombre, con peleas coreografiadas que se mezclan con gags de comedia física pura. La trama del crucero y los terroristas es apenas una excusa para enhebrar escenas de acción y humor absurdo. Para quien busca a Jackie Chan en estado de diversión, no en su registro más serio.', 'Si buscás el registro más serio de Jackie Chan, el tono payasesco de esta la desconcierta.', 'fondo'),
  (845222, 'Es un capítulo especial de la serie coreana "Kingdom", centrado en un personaje secundario que apareció apenas unos segundos antes. Funciona como precuela de venganza, con el mismo tono de horror de época que la serie. Tiene sentido verla después de haber visto las dos temporadas, no antes.', 'Si no viste Kingdom antes, el personaje de Ashin y su historia no te van a generar ningún interés particular.', 'alta'),
  (13938, 'Es un cruce bastante único entre película de kung-fu, blaxploitation y video musical de Motown, producida por Berry Gordy. Sho''nuff, el villano con pandilla, terminó siendo más recordado que el propio protagonista. Si te gusta el cine de artes marciales ochentoso con banda de sonido funk, es justo tu película.', 'La trama es una excusa para encadenar peleas y escenas musicales, sin mucha lógica entre una cosa y otra.', 'fondo'),
  (11772, 'Es terror sin efectos ni monstruos visibles, todo pasa por el sonido y lo que no se muestra. La protagonista insegura funciona como centro emocional, no solo como víctima de sustos. Envejeció mejor que la mayoría del terror de su época porque apuesta a la sugestión.', 'Si esperás sustos directos o algo visualmente explícito, esta película no va a entregar eso.', 'media'),
  (9739, 'Stallone y Wesley Snipes chocan en una comedia de acción que se ríe de un futuro aséptico y políticamente correcto. El contraste entre el policía brusco de los noventa y esa sociedad edulcorada es todo el chiste.', 'Algunos chistes sobre ese futuro ''correcto'' envejecieron de forma rara y hoy caen distinto.', 'media'),
  (152780, 'Asghar Farhadi construye esto como un mecanismo de revelaciones, donde cada personaje sabe algo que los otros no. Ahmad vuelve a París solo para firmar un divorcio y termina metido en una red de secretos ajenos. Es cine de diálogos y silencios cargados, no de escenas grandes.', 'Si no te gusta el ritmo pausado del cine de Farhadi, esta película pide paciencia desde el arranque.', 'alta'),
  (696157, 'Naomi Ackie hace playback sobre las grabaciones originales de Whitney Houston, desde el coro de Nueva Jersey hasta la cima del pop. La película no esquiva las partes más oscuras de su consumo problemático ni de su vida personal. Es biopic musical clásico, pensado para fans de su música.', 'Dura 144 minutos y sigue la estructura típica de ascenso, caída y redención sin arriesgar demasiado.', 'media'),
  (124097, 'Es un Disney Channel Original Movie sobre un chico de familia beisbolera que descubre que lo suyo es la cocina. Tiene que esconderlo de sus hermanos y de su papá. Sigue la fórmula clásica del canal: talento oculto, familia que no entiende, competencia final.', 'Si ya viste varios DCOM de esa época, la estructura del tercer acto se adivina de entrada.', 'fondo'),
  (1280282, 'Es la versión de cine del show de Netflix ''La casa de muñecas de Gabby'', con Kristen Wiig como la villana de turno. Funciona mejor si en tu casa ya conocen a los personajes y el mundo de la casa de muñecas.', 'Si no viste la serie, la cantidad de personajes y gatos puede abrumar un poco al principio.', 'fondo'),
  (513268, 'Mary J. Blige interpreta a una policía que empieza a investigar muertes inexplicables entre sus compañeros, con una fuerza sobrenatural de fondo. Lo distinto es que el terror está atado a temas de abuso de poder policial, no es solo un slasher con cámara corporal. Es más efectivo como denuncia incómoda que como película de sustos tradicional.', 'Si buscás terror de sustos constantes, el ritmo se toma su tiempo en la parte de investigación policial.', 'media'),
  (24032, 'George Burns hace de Dios como un viejito de boina y cigarro, nada solemne, que elige a un empleado de supermercado como mensajero. La gracia está en el contraste entre el tema religioso y el tono de comedia de barrio, con Burns robándose cada escena. John Denver hace de la parte más ingenua, el que tiene que convencer a todos de que esto es real.', 'El humor es bastante suave y amable, sin filo: si buscás comedia más ácida sobre religión, no la vas a encontrar acá.', 'fondo'),
  (869626, 'Nació como una serie de cortos virales y se nota: tiene ese humor de documental casero, con Marcel hablando directo a cámara. Lo que la distingue es la melancolía de fondo, la pérdida de una comunidad entera, que convive con los chistes. Funciona para adultos tanto como para chicos, no es solo una película infantil.', 'Si buscás solo comedia liviana, el duelo de fondo le resta chistes en varios tramos.', 'media'),
  (27850, 'Es la primera de la saga Disney Channel, con un mundo de brujas en convivencia pacífica en vez de terror, algo poco común para una historia de Halloween. Marnie descubriendo su magia funciona como metáfora simple de crecer y asumir quién sos. Es nostálgica para quien la vio de chico en los 2000 por el canal.', 'Si esperás algo con tensión real de Halloween, el tono acá es demasiado amable y familiar para ese género.', 'fondo'),
  (9788, 'Es una comedia adolescente de mitad de los 2000, con el gancho de fundar una universidad trucha para engañar a los padres. Funciona bien si buscás algo liviano para no pensar, con el humor absurdo típico de esa época. No esperes ironía fina, es puro gag y buena onda.', 'El humor es bastante infantil y los chistes envejecieron con el estilo de comedia de esos años.', 'fondo'),
  (617502, 'Kate Beckinsale hace de una mujer con un trastorno de ira que se controla con descargas eléctricas, una premisa que promete más de lo que la película termina dando. Es acción directa, sin vueltas, pensada para consumir rápido. Funciona si buscás algo liviano de venganza con un gancho raro.', 'El humor negro que intenta no siempre cierra, y la historia de amor queda bastante esquemática.', 'fondo'),
  (407448, 'Kathryn Bigelow filma el motel Algiers con una cámara pegada a los cuerpos, incómoda a propósito. No busca la reconstrucción histórica prolija, sino una tensión sostenida que no da respiro. Sirve para entender un episodio concreto del racismo policial en Estados Unidos, no un repaso general.', 'La escena central en el motel es muy larga y durísima, no es para ver distraído.', 'alta'),
  (736769, 'Mezcla blaxploitation, ciencia ficción y comedia de conspiración en un barrio que resulta ser el centro de algo mucho más grande. John Boyega, Jamie Foxx y Teyonah Parris arman un trío con química genuina. El estilo visual homenajea el cine de los setenta sin quedarse en la parodia.', 'El giro de género, de comedia callejera a ciencia ficción, tarda en llegar y el arranque puede sentirse lento.', 'alta'),
  (405894, 'Es una película para TV de la serie ''Recess'' de Disney, pensada para quien ya sigue a la pandilla del patio. El conflicto por los cambios en la escuela sigue el tono liviano de la serie original.', 'Si nunca viste la serie, varios chistes dependen de conocer a los personajes de antemano.', 'fondo'),
  (132144, 'Patricio Guzmán filmó este registro en tiempo real durante los últimos meses del gobierno de Allende. Tiene un valor histórico enorme por no ser una reconstrucción posterior. El material tuvo que sacarse clandestinamente del país después del golpe.', 'Pide conocimiento previo del contexto político chileno de los años 70 para aprovecharlo del todo.', 'alta'),
  (1312946, 'Es un romance de mochileros por Europa con la estética de postal que pide el género, pensado para dejarse llevar sin exigir demasiado. La protagonista debe elegir entre la vida prolijamente planeada que la espera y lo que siente en el viaje. Funciona para una tarde de desconexión, no para buscar sorpresas en la fórmula.', 'Sigue al pie de la letra las reglas del romance de verano, sin correrse de la fórmula.', 'fondo'),
  (921785, 'Cuenta el auge de un imperio casero de mixtapes piratas en Nápoles con el mismo ritmo desprolijo y vital de sus protagonistas. Funciona como retrato de época de la Italia ochentosa, de la viveza napolitana que convierte el delito en negocio familiar. Es cine popular italiano, pensado para entretener antes que para la reflexión.', 'Si no tenés referencia de la cultura pop italiana de los 80, varios chistes y guiños pierden gracia.', 'media'),
  (11777, 'Walter Matthau hace de Albert Einstein convertido en celestino, armando con sus colegas científicos todo un plan para emparejar a su sobrina con un mecánico. Es comedia romántica liviana de los 90, sin cinismo ni vueltas de tuerca. Funciona para ver en familia o para relajar la cabeza.', 'La premisa de Einstein manejando la vida amorosa de la sobrina envejeció con un aire bastante paternalista.', 'fondo'),
  (17609, 'Lars von Trier lleva el duelo de una pareja al límite en una cabaña perdida en el bosque. La puesta en escena se vuelve cada vez más perturbadora a medida que avanza.', 'Tiene escenas de violencia sexual y gráfica muy fuertes, no es para cualquier estado de ánimo.', 'alta'),
  (425001, 'Robert De Niro se presta a la comedia familiar más simple, enfrentado a su nieto por una habitación. Es humor de gags físicos pensado para ver con chicos, sin ninguna ambición extra. No busca sorprender en ningún momento.', 'Los gags se repiten bastante hacia la mitad de la película.', 'fondo'),
  (5919, 'Es uno de los grandes clásicos del cine de catástrofes de los setenta, con Paul Newman y Steve McQueen compartiendo protagónico sin pelearse por la cámara. El incendio se construye con maquetas y efectos prácticos que todavía impresionan. Dura casi tres horas, pero el desastre se toma su tiempo para escalar con lógica.', 'Dura 165 minutos y la primera hora se dedica a presentar personajes antes de que empiece el incendio.', 'media'),
  (505948, 'Una adolescente criada por una robot en un refugio subterráneo empieza a dudar de todo lo que le enseñaron cuando llega otra persona de afuera. Es ciencia ficción de ideas, con pocos personajes y mucho diálogo filoso entre ellos.', 'Es bastante más cerebral y lenta que lo que promete un afiche con robots.', 'alta'),
  (858024, 'Chloé Zhao filma la vida de Agnes, la esposa de Shakespeare, con la misma atención a los paisajes y los cuerpos que usó en Nomadland. Jessie Buckley sostiene el peso emocional de la historia casi sola. Funciona mejor si vas sin apuro, es un drama de duelo más que una biopic tradicional sobre el autor.', 'Si buscás algo centrado en Shakespeare y su obra, te vas a encontrar con una película que mira para otro lado.', 'media'),
  (44514, 'Es una animación española sobre la leyenda del Cid Campeador, pensada para público infantil con tono de aventura clásica. Funciona como introducción liviana a la figura histórica, no como versión fiel a los hechos.', 'La animación y el guion se sienten bastante por debajo de los estándares de la época.', 'fondo'),
  (660982, 'Es un spin-off tardío de la saga, con poco que ver con las películas originales más allá del nombre y el tono adolescente. Cambia el eje a cuatro amigas, pero repite la fórmula de fiesta y chistes sexuales sin mucha variación. Sirve para pasar el rato sin exigirle nada.', 'Si te gustó la trilogía original, esta entrega se siente hecha para repetir la fórmula, no para sumarle algo.', 'fondo'),
  (11348, 'Es terror de Jaume Balagueró ambientado en un hospital infantil que está cerrando, con Calista Flockhart como la enfermera que empieza a notar algo raro. La "niña mecánica" que mencionan los chicos funciona mejor como amenaza sugerida que mostrada. Tiene ese tono de terror europeo más atmosférico que de sustos encadenados.', 'El ritmo privilegia la atmósfera del hospital por sobre los sustos directos, así que si buscás algo más visceral te va a quedar corto.', 'media'),
  (25059, 'Las mismas tres mascotas de la primera Bienvenidos a Casa se pierden ahora en San Francisco en lugar del bosque. Chance, Sassy y Shadow tienen que cruzar la ciudad para volver con la familia antes de que se vayan de vacaciones. Es cine familiar de los 90 sin sorpresas, pensado para repetir la fórmula que funcionó antes.', 'Es básicamente la misma película que la primera con otro escenario, pierde la sorpresa de la original.', 'fondo'),
  (42172, 'Paul Schrader cruza al padre calvinista con el mundo que más desprecia, y de ahí sale toda la tensión. George C. Scott juega la rigidez moral como quien contiene una explosión. Funciona mejor si te interesa ese choque religioso que si buscás un thriller de rescate convencional.', 'El tramo del detective privado se estira más de lo que la trama necesita.', 'alta'),
  (432527, 'Bhansali construye esto a pura escala: escenografía, vestuario y números musicales pensados para pantalla grande. Ranveer Singh se roba la película haciendo del sultán Khilji un villano excesivo, mucho más magnético que los protagonistas virtuosos. Es cine popular indio en su versión más ornamentada, no un drama íntimo de personajes.', 'Dura 163 minutos y el tramo final de asedio repite varias veces la misma tensión.', 'alta'),
  (24420, 'Rachel McAdams ama a un hombre que viaja en el tiempo sin poder controlarlo, lo que convierte cada reencuentro en algo incierto. Es romance fantástico con una premisa que usa el tiempo como obstáculo, no como truco.', 'La lógica de los viajes en el tiempo no se sostiene mucho si te pones a pensarla.', 'media'),
  (41300, 'Cantinflas repite el molde que lo hizo popular: el personaje humilde que termina parado de igual a igual frente al poder. Es comedia política liviana, con su forma particular de hablar sin decir nada concreto.', 'El humor depende mucho del juego de palabras de Cantinflas, así que pierde fuerza si no estás acostumbrado a su manera de hablar.', 'fondo'),
  (45371, 'Cierra la trilogía de Peter Morgan sobre Tony Blair, después de ''The Deal'' y ''The Queen'', con Michael Sheen repitiendo el papel. Retrata la relación con Clinton como un estudio de poder más que como biografía sentimental.', 'El peso está en el diálogo político, así que si no te interesa esa época te puede resultar árido.', 'alta'),
  (60803, 'Cierra la serie Disney Channel de los gemelos del crucero bajándolos a tierra firme para un plan de investigación genética. Es una película pensada para quien ya siguió la serie de chico. Funciona más por nostalgia que por la trama en sí.', 'Si no viste la serie antes, varios chistes y referencias a personajes no se entienden.', 'fondo'),
  (1597, 'La gracia está en la tensión incómoda entre Ben Stiller y Robert De Niro, un suegro exagente de la CIA al que le cuesta confiar en cualquiera. Cada gesto de Greg para quedar bien sale peor que el anterior.', 'El humor se basa en situaciones vergonzosas, si el cringe no te causa gracia se te va a hacer largo.', 'media'),
  (164457, 'Christian Bale hace de un obrero de acería que ve a su hermano, veterano de Irak, meterse en peleas clandestinas cada vez más peligrosas. Es un drama gris sobre pueblos industriales que se vacían, más cercano al cine social que al thriller de venganza que sugiere el afiche. Casey Affleck y Woody Harrelson completan un elenco sólido.', 'Si esperás un thriller de acción con ritmo rápido, el tono es mucho más lento y deprimido.', 'media'),
  (823766, 'Florence Pugh interpreta a una enfermera que tiene que observar, sin intervenir, a una nena que dice no comer desde hace meses. La tensión sale de la duda entre fe y manipulación, en un pueblo cerrado sobre sí mismo. Tiene un arranque poco convencional que avisa que estás viendo una ficción construida.', 'El ritmo es pausado y el pueblo irlandés del siglo diecinueve pide paciencia antes de que la trama se tense.', 'alta'),
  (93863, 'Es una película de Antonioni sobre una actriz atrapada en el sistema de estudios, con ese estilo frío y observacional típico del director. Interesa más a quien busca cine de autor italiano que un drama convencional.', 'El ritmo es deliberadamente distante: Antonioni no busca que te identifiques con la protagonista.', 'media'),
  (105768, 'Es la tercera de la saga Flicka, ya sin el elenco original de las dos primeras. La relación entre Kelly y el caballo salvaje repite la fórmula de superación personal a través del cuidado animal.', 'Si viste las dos primeras Flicka esperando la misma historia, acá el elenco y el tono cambiaron bastante.', 'fondo'),
  (998022, 'Es una película alemana que arma tensión con lo más chico: una sospecha de robo en una escuela secundaria. Lo que la hace fuerte es cómo muestra que no hay decisión correcta cuando padres, colegas y alumnos exigen algo distinto. Se siente como un termómetro de cómo funcionan hoy las instituciones educativas.', 'Si esperás un thriller con vueltas de trama, esta película se mueve en la incomodidad cotidiana, no en el suspenso clásico.', 'alta'),
  (21301, 'La secuela mete la amenaza de la gentrificación en el local y usa eso para hablar de barrio, no solo de chistes de peluquería. El elenco sigue siendo lo mejor: cada personaje tiene su numerito y se lo deja respirar. Si te gustó la primera por el ambiente de barbería, esta mantiene ese tono sin perder el costado social.', 'El costado de denuncia social a veces le gana al chiste y el tono se siente desparejo.', 'media'),
  (24655, 'Es puro cine de serie B de los 70, con un auto poseído que nunca necesita explicar su origen. Sigue la fórmula de amenaza imparable que puso de moda Tiburón, trasladada a un pueblo chico y un vehículo. Para quien disfruta el terror de la época sin explicaciones ni grandes presupuestos.', 'La película nunca explica el origen del auto y no hace falta esperar que lo haga.', 'media'),
  (536437, 'Robert Rodriguez arma un thriller de identidad con vueltas de tuerca constantes, al estilo de sus películas más genéricas de los últimos años. Ben Affleck está correcto pero sin mucho margen para actuar, la película vive de los giros de guion. Es para ver sin pedirle demasiado, como entretenimiento de una tarde.', 'Los giros se acumulan tanto que en el tramo final cuesta seguir la lógica interna.', 'media'),
  (113, 'Kim Ki-duk cuenta una vida entera a través de las estaciones en un monasterio flotante, con muy poco diálogo. Es cine contemplativo, donde cada plano pide que te quedes quieto y mires. No es para ver distraído ni con apuro.', 'El ritmo es extremadamente contemplativo y casi no hay diálogo, así que pide mucha paciencia.', 'alta'),
  (10669, 'Cuatro amigos de ciudad bajan un río salvaje antes de que lo inunden para una represa, y lo que arranca como escapada se convierte en pesadilla. Burt Reynolds lidera un grupo que se enfrenta a algo mucho más hostil que la naturaleza del río. Es un clásico tenso sobre lo rápido que se puede perder el control fuera de la ciudad.', 'Tiene una escena muy dura que todavía hoy genera incomodidad y marcó la fama de la película.', 'alta'),
  (249164, 'Chloë Grace Moretz revive sus recuerdos mientras decide si sigue con vida después del accidente que la deja al borde de la muerte. Apunta directo al drama adolescente lacrimógeno, sin disimularlo.', 'Si el tearjerker adolescente no te genera nada, el drama se va a sentir forzado.', 'media'),
  (818647, 'Es un romance adolescente español basado en una novela de Wattpad, con una protagonista obsesionada con el vecino misterioso. Apuesta fuerte a la intensidad emocional típica de ese formato.', 'Tiene escenas bastante más subidas de tono que el romance adolescente promedio.', 'fondo'),
  (9718, 'Will Ferrell hace de un piloto de NASCAR engreído que pierde todo cuando aparece un rival francés mucho más hábil que él. Es comedia de absurdo puro, con gags que se estiran a propósito hasta el ridículo. Funciona mejor si ya te gusta el humor bruto de Ferrell en otras películas con Adam McKay.', 'Si el humor de Will Ferrell no te cierra en general, esta no va a ser la excepción.', 'fondo'),
  (41305, 'Cantinflas repite al personaje torpe metido en problemas que no entiende, esta vez con un ángulo fantástico poco habitual en su filmografía. Es más curiosidad dentro de su carrera que una historia religiosa seria.', 'El costado fantástico con el diablo es excusa para gags, no esperes una reflexión real sobre el bien y el mal.', 'fondo'),
  (674607, 'Es un thriller francés que arranca como sátira de los grupos de supervivencialistas obsesionados con el apocalipsis y de a poco se pone tenso en serio. La gracia está en ese quiebre: lo que empieza como entrenamiento ridículo termina siendo una situación de vida o muerte real. Dura poco más de ochenta minutos y no se anda con vueltas.', 'Si esperás una sátira sostenida de punta a punta, la segunda mitad abandona el humor por completo.', 'media'),
  (42500, 'Burt Lancaster hace de un sheriff tan rígido con la ley que se vuelve casi tan violento como los que persigue. Dirige Michael Winner, el mismo que después hizo Death Wish, y se nota ese interés por personajes duros sin heroísmo fácil. El elenco suma a Robert Ryan y Lee J. Cobb, dos pesos pesados del género.', 'Lancaster juega un personaje deliberadamente antipático, así que cuesta encontrar a quién bancar en la historia.', 'media'),
  (670439, 'Está basada en un hecho real poco conocido: un internado inglés que educaba a hijas de nazis justo antes de la guerra. Eddie Izzard coescribió el guion y lo protagoniza, con un thriller de espías más modesto que vistoso.', 'Si esperás un thriller de acción, el ritmo es de espionaje de época, más pausado que trepidante.', 'media'),
  (14172, 'Van Damme deja de lado el tono liviano de otras películas suyas de la época. Se mete en algo más oscuro, con la Tríada china como amenaza real y no de cartón. La relación con la nena rescatada del barco funciona mejor de lo esperado para este tipo de acción directa a video.', 'Las escenas de acción son más escasas de lo que esperás de una película de Van Damme.', 'media'),
  (244264, 'Lynn Shelton dirige esta comedia sobre una mujer de casi treinta que se esconde de su propia vida adulta con una adolescente de dieciséis. Keira Knightley juega con un acento americano y un personaje bastante perdido, lejos de sus papeles de época. Es una comedia pequeña, sin grandes ambiciones de taquilla.', 'La premisa de una adulta escapando con una adolescente puede resultar incómoda si no te metés en el tono liviano.', 'media'),
  (586461, 'Haley Bennett interpreta a un ama de casa embarazada que empieza a tragar objetos peligrosos, un trastorno real llamado pica. La película lo usa para hablar de control y sumisión doméstica, más que como curiosidad clínica. El tono es frío, casi de laboratorio.', 'Las escenas de ingesta de objetos son explícitas y pueden resultar difíciles si sos aprensivo con ese tipo de imágenes.', 'media'),
  (9787, 'Cuenta la historia real de los Z-Boys, el grupo de skaters de Venice Beach que vino del surf. Tiene el pulso de las películas de grupo rebelde de los setenta, con Heath Ledger como mentor algo perdido. La fotografía capta bien la California de esa época.', 'Si el mundo del skate no te atrae, buena parte del metraje son maniobras sobre la tabla.', 'media'),
  (332270, 'Está basada en la historia real de Lyudmila Pavlichenko, la francotiradora soviética más letal de la Segunda Guerra Mundial. Mezcla el relato bélico con una historia de amor que queda en segundo plano frente a su carrera militar. Es cine bélico contado desde el lado soviético, poco habitual en la cartelera occidental.', 'Es una coproducción ucraniano-rusa de 2015, un dato que hoy resulta extraño dado lo que pasó después entre ambos países.', 'media'),
  (498402, 'Valérie Lemercier dirige y se anima a interpretar a su personaje desde la infancia hasta la adultez, algo que genera un efecto raro y a la vez conmovedor. No es un biopic prolijo al estilo Hollywood, tiene un tono propio entre el homenaje y la rareza. Funciona mejor para quien disfruta cuando el género se anima a correrse del molde.', 'La misma actriz interpreta al personaje de niña y esa decisión resulta rara al principio.', 'media'),
  (7095, 'Robin Williams hace de un chico de diez años atrapado en un cuerpo que envejece cuatro veces más rápido, y la película juega todo a su carisma. Francis Ford Coppola dirige algo mucho más liviano que el resto de su filmografía, casi un encargo. Funciona como comedia familiar con un costado agridulce de fondo.', 'El tono cambia bastante entre la comedia física y los momentos de drama sobre la enfermedad.', 'fondo'),
  (833591, 'Es la versión hispana del formato italiano ''Perfetti sconosciuti'', que ya tuvo versiones en más de una docena de países. La premisa es siempre la misma: una cena de amigos donde todos dejan el celular sobre la mesa. La tensión crece a medida que las notificaciones empiezan a destapar secretos.', 'Si ya viste otra versión del mismo formato, italiana o de otro país, la mecánica de la noche es prácticamente igual.', 'alta'),
  (98514, 'Es la primera película de Kelly Reichardt, la misma directora de ''Wendy and Lucy'' y ''First Cow'', y ya se nota su gusto por personajes pasivos y tiempos muertos. La pareja protagonista duda tanto que la fuga nunca termina de arrancar.', 'Si buscás tensión real de road movie criminal, esta la va a frustrar a propósito.', 'media'),
  (401743, 'Cuenta la vida de Madalyn Murray O''Hair, la atea más famosa del país, con Melissa Leo construyendo un personaje tan convincido como insoportable a propósito. Netflix la hizo con bajo perfil, pero el guion no esquiva lo turbio del personaje real.', 'Si buscás un retrato heroico del activismo ateo, la película elige mostrar a O''Hair en su costado más tóxico y egocéntrico.', 'media'),
  (9546, 'Denzel Washington y John Lithgow se sacan chispas en un thriller de venganza policial de los 90, con una escalada de trampas cada vez más retorcidas. Es puro entretenimiento de acción sin pretensiones de profundidad. Ideal para quien quiere un villano que se toma la revancha muy en serio.', 'Los giros de la venganza se vuelven cada vez más exagerados y piden no pensar demasiado en la lógica.', 'media'),
  (21481, 'Tia y Tamera Mowry hacen de gemelas brujas separadas al nacer que se reencuentran justo antes de cumplir 21 años. Es un Disney Channel Original Movie clásico de los 2000, con magia liviana y mensaje familiar. Funciona para ver con chicos o por nostalgia de esa época.', 'La lógica de la magia se explica poco y rápido, pensada para un público infantil que no necesita que cierre del todo.', 'fondo'),
  (318121, 'Paul Rudd hace de un cuidador novato que se engancha con un pibe con distrofia muscular, deslenguado y con ganas de ver cosas raras de la ruta. Es un road movie chico, de tono agridulce, que evita el dramatismo fácil sobre la discapacidad. Funciona por la química entre los dos protagonistas, no por sorpresas de guion.', 'Si ya viste muchas road movies de duelo con humor, el recorrido se siente conocido.', 'media'),
  (590995, 'Reboot de la película de brujas adolescentes de los noventa, con un grupo nuevo de protagonistas. Toca identidad y poder femenino de forma más directa que la película que la inspiró. Funciona como entrada liviana al género de brujería adolescente.', 'Si viste la original de 1996, esta versión se siente bastante más domesticada en comparación.', 'media'),
  (9945, 'John Carpenter traslada su estética de western fronterizo a una cacería de vampiros sucia y violenta, lejos del vampiro romántico de la época. James Woods hace de cazador cínico y sin códigos, ni heroico ni simpático. Para quien busca terror ochentoso tardío con onda de película de acción.', 'El tratamiento de los personajes femeninos envejeció peor que el resto de la película.', 'media'),
  (31906, 'Clint Eastwood hace de un soldado herido que termina refugiado en un internado de mujeres durante la Guerra Civil norteamericana, lejos de su papel habitual de héroe. Es la versión original que Sofia Coppola remakeó en 2017, acá con un tono más sucio y gótico. Funciona para quien ya vio el remake y quiere comparar el tono.', 'El relato retrata el deseo femenino con una mirada bastante propia de 1971, más cruda que elegante.', 'media'),
  (252838, 'Kevin Hart hace lo que mejor hace, hablar rápido y robarse cada escena, y acá tiene margen para explotarlo. La premisa del padrino de alquiler da para gags físicos y situaciones incómodas bien resueltas. Si ya viste varias comedias de bodas americanas no te va a sorprender, pero cumple.', 'El tramo final se pone sentimental de golpe y pierde el ritmo cómico que traía.', 'fondo'),
  (339095, 'Thriller de atraco con premisa de ciencia ficción: una señal del gobierno que anula el impulso criminal en todo el país. La idea termina funcionando más como excusa para el golpe final que como concepto desarrollado. Edgar Ramírez lidera un elenco correcto en una producción visualmente prolija.', 'Dura 148 minutos para una trama de atraco bastante simple, y el tramo medio se siente estirado.', 'media'),
  (8324, 'Linklater arma un mosaico con el ejecutivo que investiga la carne contaminada, los trabajadores inmigrantes del matadero y los adolescentes del local de comida rápida. Prioriza el realismo incómodo de la cadena alimenticia por sobre la denuncia grandilocuente. Funciona para quien le interesa el detrás de escena de la industria más que un thriller con ritmo.', 'No busques una trama central con villano: es un mosaico de historias que no cierran entre sí.', 'media'),
  (4710, 'Godard retrata a los jóvenes parisinos de los 60 entre el deseo, la política y el pop, con un estilo fragmentado de viñetas más que de trama tradicional. Chantal Goya como aspirante a cantante pop le da un contraste directo al idealismo más serio de Paul. Es más un ensayo sobre una generación que una historia de amor convencional.', 'Si buscás una historia romántica con estructura clara, el formato de fragmentos sueltos no te va a cerrar.', 'alta'),
  (467482, 'Luchini juega a un ejecutivo que vive a las corridas y de repente no puede completar una frase. Ahí está lo mejor de la película: verlo pelear con el lenguaje que antes dominaba. Es un drama de rehabilitación sin golpes bajos forzados, con la logopeda como contrapeso calmo.', 'El tramo central avanza con pasos chicos, al ritmo lento de la rehabilitación misma.', 'media'),
  (11589, 'Clint Eastwood lidera un grupo de soldados que decide robar un cargamento de oro nazi en medio de la Segunda Guerra. Mezcla la acción bélica con un humor bastante irreverente para la época en que se filmó. Donald Sutherland hace de un hippie anacrónico que se roba varias escenas.', 'Dura 144 minutos y el tono cambia bastante entre la comedia absurda y la acción bélica seria.', 'media'),
  (3021, 'John Cusack sostiene casi toda la película solo, encerrado en una habitación de hotel que se va volviendo cada vez más hostil. Funciona como ejercicio de tensión en espacio cerrado más que como terror clásico.', 'El desenlace se aleja bastante del cuento original de Stephen King, algo que a los fans del relato les molestó.', 'media'),
  (10468, 'Sandra Bullock cambia el registro de comedia romántica para meterse en una clínica de rehabilitación, con bastante humor pese al tema. Es más liviana de lo que un drama sobre adicciones suele ser, sin dejar de tomarse en serio el proceso. Funciona como entrada accesible al tema, no como retrato crudo.', 'Si buscás un drama crudo sobre adicciones, el tono acá es más liviano y comercial de lo esperado.', 'media'),
  (108726, 'Ben Kingsley hace de un hombre que planta bombas en Colombo y negocia por teléfono con un investigador, en un pulso de dos voces. Es el remake de la película india ''Un miércoles cualquiera'', con el mismo esqueleto de thriller moral.', 'Si esperás una de acción con explosiones, esto es más diálogo tenso en una oficina que persecuciones.', 'alta'),
  (44040, 'Cinco desconocidos quedan encerrados en un ascensor y la película apuesta todo a la paranoia de no saber quién es el responsable. Nace de una idea de M. Night Shyamalan, aunque la dirige otro.', 'Transcurre casi toda en el mismo ascensor, la premisa se estira más de lo que da.', 'media'),
  (9709, 'Pawlikowski filma el verano inglés como una burbuja que separa a estas dos chicas del resto del mundo. Emily Blunt, en uno de sus primeros papeles, construye un personaje que seduce sin que quede claro qué quiere. Es una película de clima más que de trama, pide paciencia.', 'Si buscás psicología clara de personajes, la ambigüedad de Tamsin te va a resultar frustrante.', 'media'),
  (41662, 'Altman arma un juego de identidades entre las dos protagonistas que se va volviendo cada vez más onírico y perturbador. Shelley Duvall y Sissy Spacek sostienen una película que avanza más por atmósfera que por trama convencional. Es para quien banca el cine que no explica lo que muestra.', 'La trama se vuelve deliberadamente ambigua y no ofrece respuestas cerradas sobre lo que pasó.', 'alta'),
  (443009, 'Joaquin Phoenix interpreta a John Callahan, el dibujante que quedó tetrapléjico tras un accidente y encontró en el humor negro su forma de procesarlo. Gus Van Sant no suaviza el proceso de adicción ni lo convierte en inspiración fácil. Jonah Hill sorprende en un rol dramático como su padrino de Alcohólicos Anónimos.', 'El relato salta bastante en el tiempo y puede costar ubicarse en qué momento de la vida de Callahan estás.', 'alta'),
  (10483, 'Jason Statham compite en una carrera a muerte organizada dentro de una cárcel, pura adrenalina de autos blindados y explosiones. No hay vueltas: va directo a la acción y no pretende otra cosa.', 'La trama es apenas una excusa para las carreras, no esperes desarrollo de personajes.', 'fondo'),
  (174, 'Es la despedida del elenco original, con la Guerra Fría como espejo directo del conflicto entre la Federación y los Klingon. Nicholas Meyer, que ya había dirigido la mejor entrega de la saga, vuelve con un policial espacial de intriga política. Es de las más respetadas incluso por quienes no son fanáticos de la ciencia ficción pura.', 'La trama política pide haber visto algo antes de la saga para entender tensiones y personajes.', 'alta'),
  (11322, 'Michael Mann filma a John Dillinger con la misma frialdad visual que usó en Collateral, más interesado en el procedimiento policial que en la acción. Christian Bale y Johnny Depp juegan al gato y al ratón sin demasiado dramatismo de por medio.', 'El ritmo es pausado para ser una película de gánsteres, si esperás tiroteos constantes te va a aburrir.', 'media'),
  (26337, 'Es un neo-noir de los 90 que homenajea directamente al cine negro clásico, con Ed Harris como el detective que termina metido en el caso que investiga. La dirigió John Bailey, que venía de ser director de fotografía, y eso se nota en el cuidado visual de cada escena. Quedó bastante oculta por líos de distribución en su estreno, pero es una de las noir menores más rescatadas por la crítica.', 'Si conocés mucho noir clásico, vas a reconocer casi todos los giros antes de que lleguen.', 'alta'),
  (22559, 'James Cameron filma en IMAX 3D las mismas profundidades marinas que lo obsesionaron durante ''Titanic'', buscando criaturas que parecen de otro planeta. El documental conecta de forma explícita la exploración submarina con la búsqueda de vida extraterrestre.', 'Si no lo ves en pantalla grande, el formato pensado para IMAX 3D pierde bastante impacto.', 'media'),
  (65291, 'Son seis historias cortas con distintos equipos de animación, cada una centrada en un Linterna distinto a lo largo de la historia del Cuerpo. Funciona como una introducción al mito de Linterna Verde sin pasar por la película live action. Sirve para fans de DC que quieren contexto antes de leer los cómics.', 'Al ser seis historias sueltas, el nivel de cada segmento es bastante desparejo.', 'fondo'),
  (18736, 'Es la película que cerró la serie de Disney Channel, con el gancho turístico de Roma y el enredo de identidades. Hilary Duff hace doble papel y la película vive de ese contraste entre la Lizzie torpe de siempre y la estrella pop. Funciona para quien siguió la serie, como cierre con más glamour que el programa.', 'Si no viste la serie antes, el cambio de tono hacia algo más estrella pop puede resultar raro.', 'fondo'),
  (10617, 'Jet Li en su mejor etapa de wuxia, con coreografías de Tsui Hark que mezclan artes marciales clásicas con un pulso de aventura de capa y espada. Es más política de lo que promete el título: habla del choque entre la tradición china y la llegada de armas y comerciantes extranjeros. Para quien busca acción coreografiada con cuerpo y oficio, no efectos digitales.', 'Si buscás acción constante, el tramo político del medio corta bastante el ritmo.', 'media'),
  (9701, 'Charlize Theron se mete en un ambiente hostil de verdad: una mina donde las mujeres son toleradas, no bienvenidas. La película no dramatiza el acoso para generar impacto, lo muestra como rutina diaria, lo que incomoda más. Vale para quien quiera un drama social sin golpes bajos innecesarios.', 'El tramo judicial final se vuelve más convencional que el resto de la película.', 'media'),
  (13275, 'James Franco es un pibe de clase trabajadora que entra contra todo pronóstico a la academia naval de Annapolis. La película sigue de cerca el entrenamiento físico y el boxeo interno como prueba de carácter. Es cine de superación clásico, sin vueltas de tuerca.', 'Si ya viste Rocky o alguna otra película de academia militar, acá no hay sorpresas en la estructura.', 'media'),
  (1654, 'Es el antecedente directo de todas las películas de comando de criminales con misión suicida que vinieron después. Lee Marvin arma un grupo imposible y la película se toma su tiempo en mostrar cómo entrenan antes de la acción final. Para quien le gusta el cine bélico de grupo, con tensión interna entre los propios personajes.', 'La primera mitad es toda entrenamiento y construcción de personajes, sin acción todavía.', 'media'),
  (274854, 'Vin Diesel juega a un cazador de brujas inmortal en una fantasía urbana que buscaba arrancar una saga propia. Funciona como entretenimiento de acción liviana más que como propuesta original.', 'Se nota que estaba pensada para tener secuelas que nunca llegaron, algunos hilos quedan sueltos.', 'media'),
  (614560, 'David Fincher filma en blanco y negro los años en que Herman Mankiewicz escribió el guion de Ciudadano Kane. Lo muestra metido en los líos políticos y los excesos de Hollywood de los años treinta. Es una película para cinéfilos, con referencias constantes a la industria de esa época.', 'Si no tenés algo de contexto sobre Ciudadano Kane y el Hollywood clásico, bastante del relato se te va a escapar.', 'alta'),
  (33542, 'Jackie Chan hace sus propias acrobacias entre el Bronx y Vancouver disfrazado de Nueva York. Las coreografías de pelea son el motivo real para verla, no la trama de diamantes. Es acción física de la vieja escuela, sin efectos digitales.', 'La trama de bandas y diamantes es solo una excusa para llegar a la próxima pelea.', 'fondo'),
  (9410, 'Es Dickens trasplantado a Nueva York y Florida, con la obsesión por Estella convertida en motor central más que la trama de ascenso social del original. Ethan Hawke y Gwyneth Paltrow llevan el peso romántico por encima de la crítica social de la novela. Funciona mejor si no esperás fidelidad al libro.', 'Si leíste la novela de Dickens, esta versión recorta y cambia bastante para quedarse con la historia de amor.', 'media'),
  (8326, 'Disney adaptó la novela de Louis Sachar sin edulcorarla del todo, algo raro para una película familiar de esos años. La estructura salta entre el presente en el campo de castigo y una historia de generaciones atrás, y ambas encajan como piezas de rompecabezas. Funciona tanto para chicos como para adultos que la vieron de grandes.', 'Los saltos temporales piden algo de atención, un chico muy chico se puede perder con la historia paralela.', 'media'),
  (27970, 'Es el primer hombre lobo del cine de Hollywood, seis años antes de que Universal hiciera El Hombre Lobo con Lon Chaney Jr. Acá el maquillaje es mucho más sobrio, casi humano, porque Henry Hull no quiso cubrirse toda la cara. La historia suma un costado de ciencia ficción botánica, con un científico obsesionado por una flor del Tíbet.', 'Si esperás la transformación completa en bestia de los hombres lobo posteriores, acá el maquillaje se queda corto.', 'media'),
  (21845, 'Es comedia familiar noventosa con el gancho fantástico de siempre: un pibe con un don imposible que termina jugando con profesionales. Pensada para ver en familia, sin pretensiones y con el humor físico típico de la época. Si buscás algo realista sobre béisbol, no es el lugar.', 'El humor es bien noventoso y algunos chistes envejecieron mal.', 'fondo'),
  (11463, 'La reconstrucción de los combates aéreos usa aviones reales de época y todavía impresiona por la escala, mucho antes de los efectos digitales. El elenco es coral y gigante, lo que hace que ningún personaje individual termine de profundizarse. Para quien va por la espectacularidad bélica más que por el drama humano.', 'Con un elenco tan grande, cuesta engancharse con algún personaje en particular.', 'media'),
  (433247, 'Angelina Jolie dirige esto desde el punto de vista de una nena de cinco años durante el genocidio de los Jemeres Rojos. La cámara se queda a la altura de la protagonista, así que el horror llega filtrado por su confusión, no explicado. Es un relato histórico que no busca explicar el conflicto, busca que lo sientas desde adentro.', 'Es una película dura sobre un genocidio real, no la mires esperando un drama liviano de superación.', 'alta'),
  (28032, 'Don Bluth, el mismo de En busca del valle encantado, le da a esta versión del cuento un aire más oscuro que el Disney habitual. Pulgarcita atraviesa secuestros de sapos y el acoso de un escarabajo antes de llegar al príncipe Cornelius. Es animación clásica con canciones, pensada para chicos pero con algo de atmósfera de cuento gótico.', 'Las canciones no quedaron tan pegadizas como las de otras películas de animación de la época, el tramo del medio se estira.', 'fondo'),
  (38810, 'Yorgos Lanthimos construye un mundo cerrado con una lógica propia, filmado con una distancia fría que incomoda a propósito. No hay explicación ni contexto: el extrañamiento es el punto, no un misterio para resolver. Es cine de autor griego, incómodo, con un humor negro muy seco.', 'Si necesitás empatizar con los personajes o un ritmo narrativo clásico, esta te va a frustrar.', 'alta'),
  (1242384, 'Es un documental de Netflix sobre cómo 4chan pasó de foro under a motor de teorías conspirativas y caos real. Tiene entrevistas con gente que estuvo metida en esas comunidades desde adentro.', 'Asume que ya sabés algo de memes e internet under, si no, algunas referencias quedan sueltas.', 'media'),
  (4584, 'Emma Thompson adapta a Jane Austen con un guion propio y hace de la hermana razonable, mientras Kate Winslet es la pasional. Ang Lee filma el drama de clase y matrimonio de la Inglaterra rural con una elegancia muy controlada. Es romance de época clásico, de los que premian la paciencia más que la sorpresa.', 'Si no te gusta el ritmo pausado del drama de época inglés, esta no te va a cambiar la opinión.', 'media'),
  (2789, 'Riddick pasa de la supervivencia de Pitch Black a una trama de política interestelar mucho más grande. Vin Diesel sigue al mando, pero ahora el enemigo es un imperio entero.', 'El universo y la mitología que presenta son bastante más densos, cuesta entrar si no viste la primera.', 'alta'),
  (1061117, 'Cuenta la historia real de Kai, el hitchhiker del hacha, que se hizo viral en 2013 por una entrevista callejera. Después de la fama terminó metido en una espiral judicial bastante más grave que el video que lo hizo conocido. Funciona como estudio de caso sobre qué hace la fama viral con alguien que ya venía con problemas serios.', 'Si solo te interesa el morbo del crimen, te vas a aburrir en la parte sobre su vida antes de ser viral.', 'media'),
  (37495, 'Chris Morris se mete con el humor en un grupo de terroristas torpes, y logra que la incomodidad sea parte de la gracia. Te reís y después te preguntás si estaba bien reírte. Funciona mejor para quien banca la comedia negra sin red de seguridad.', 'El humor incómodo sobre terrorismo puede resultar excesivo para quien busca una comedia liviana.', 'alta'),
  (672741, 'Megan Fox pasa buena parte de la película esposada a un cadáver, en una casa aislada en la nieve. De ahí arranca la lucha por escapar, con poca gente más en pantalla. El aislamiento invernal funciona tanto de escenografía como de amenaza.', 'La premisa del cadáver esposado se resuelve rápido y el resto queda en manos del thriller de asesinos a sueldo más genérico.', 'media'),
  (10102, 'Cuatro amigos burgueses deciden comer hasta morir y se encierran en una mansión con la decisión ya tomada. Marco Ferreri lo filma en serio, no como chiste ni como comedia negra. Es cine de autor incómodo a propósito, pensado para generar rechazo.', 'Las escenas de comida y cuerpo son explícitamente repulsivas en partes, generó escándalo cuando se estrenó en Cannes.', 'media'),
  (438674, 'S. Craig Zahler dirige esto con su ritmo marca registrada: diálogos largos, violencia seca y nada de apuro. Mel Gibson y Vince Vaughn juegan a policías que ya no encajan en ningún lado. Es un policial duro, pensado para quien banca el cine lento antes de la explosión.', 'Dura 159 minutos y el arranque es deliberadamente lento, pide paciencia antes de que la trama se active.', 'alta'),
  (4520, 'Jude Law y Michael Caine se intercambian los papeles que tuvieron en la versión original de 1972, con guión de Harold Pinter. Todo pasa en una casa entre dos hombres jugando un juego cada vez más retorcido. Es puro duelo actoral y de diálogo, sin casi nada más.', 'Si buscás acción o ritmo rápido, acá hay solo dos actores hablando en una casa.', 'alta'),
  (9684, 'Sean Penn hace de un guitarrista de jazz ficticio de los años 30, obsesionado con la idea de que Django Reinhardt es mejor que él. Woody Allen arma la película como un falso documental, con testimonios que comentan la vida del personaje. Funciona para quien disfruta el jazz y el cine de Allen de esa década.', 'El protagonista es insoportable a propósito, cuesta simpatizar con él en el primer tramo.', 'media'),
  (6575, 'Parodia del biopic musical, pensá en Johnny Cash o Ray Charles, que exagera cada cliché del género hasta el absurdo. John C. Reilly canta en serio, y eso hace que el humor funcione mejor que si fuera puro chiste. Tiene cameos que se disfrutan más si conocés los biopics que parodia.', 'Si no conocés los biopics musicales que parodia, buena parte de los chistes pierde fuerza.', 'media'),
  (24767, 'Es el clásico Disney de superación de los 90: la carrera de trineos funciona como excusa para la historia de un pibe que de golpe debe sostener a su familia. Está filmada con el frío y la nieve como protagonistas, tanto como los perros. Para ver en familia, con el tono clásico de las aventuras Disney.', 'Sigue al pie de la letra la fórmula Disney de superación, sin salirse del libreto en ningún momento.', 'fondo'),
  (10994, 'Michelle Pfeiffer juega a una madre artista y posesiva que termina presa, y la película sigue a la hija pasando de hogar sustituto en hogar sustituto intentando armar su propia identidad. Cada casa funciona casi como un capítulo distinto, con Renée Zellweger y Robin Wright completando el elenco. Es un drama de formación dura, sin golpes de efecto fáciles.', 'Si buscás un ritmo ágil, los cambios de hogar hacen que la historia se sienta episódica.', 'media'),
  (582596, 'Lauren Lapkus se la banca entera como la Missy equivocada, una fuerza descontrolada que arrastra a un ejecutivo acartonado. Es comedia física sin vergüenza, pensada para reírse sin pensar mucho. No busca nada más profundo que el gag siguiente.', 'El humor es bastante bobo y depende de que te copes con los excesos del personaje de Lapkus.', 'fondo'),
  (28769, 'Es una versión musical del clásico de Dickens, con Kelsey Grammer como Scrooge y canciones de Alan Menken. Funciona bien para ver en familia en diciembre, pero el tono es de musical de Broadway, no de drama navideño clásico.', 'Si no te cierran los musicales, los números cantados cortan el ritmo de la historia cada pocos minutos.', 'fondo'),
  (44655, 'Es un melodrama mexicano dirigido por Luis Buñuel, con Rosita Quintana como la mujer que desordena una hacienda entera. Buñuel juega con los clichés del género de la época, con un tono más irónico que el de un melodrama convencional.', 'Si buscás el surrealismo típico de Buñuel, acá está mucho más contenido por tratarse de un encargo de estudio.', 'media'),
  (274855, 'Es una de catástrofes climáticas con Gerard Butler en modo acción pura, de esas que apuestan todo a la escala del desastre. Sirve para desconectar sin pedirle demasiado al guion.', 'La ciencia que explica la tormenta artificial es bastante disparatada, no la mires buscando coherencia.', 'fondo'),
  (600583, 'Benedict Cumberbatch juega a la masculinidad tóxica como una actuación constante, nunca del todo genuina. Jane Campion deja que el paisaje de Montana se sienta tan hostil como los personajes. Avanza por gestos y miradas, no por diálogo explicativo.', 'Si necesitás que te expliquen lo que pasa, esta película no lo hace nunca.', 'alta'),
  (34996, 'Ferrara filma el vampirismo como metáfora de la adicción y de la culpa, con la protagonista citando a Nietzsche entre mordida y mordida. El blanco y negro granulado y el tono filosófico la alejan del vampiro clásico de terror. Funciona para quien busca algo cerebral; de gore hay de sobra igual.', 'El tono filosófico se vuelve denso si no te interesan las citas a Nietzsche y Sartre en los diálogos.', 'alta'),
  (749142, 'Es una coproducción ucraniana-suiza sobre una gimnasta de 15 años que entrena en Suiza. Mientras tanto su madre cubre las protestas del Euromaidán en Kiev como periodista. Mezcla el drama deportivo de alto rendimiento con el peso de la distancia familiar en medio de un conflicto político real.', 'El costado deportivo y el político conviven en paralelo, y si no conocés nada del Euromaidán el contexto puede costar un poco.', 'media'),
  (1911, 'Un noble árabe termina metido con un grupo de vikingos que pelean contra algo que al principio parece sobrenatural. Antonio Banderas hace de narrador curioso en un mundo que no es el suyo, lo que le da otro ángulo al vikingo de siempre. Tiene acción directa, basada en una novela de Michael Crichton.', 'La producción tuvo reshoots conocidos y se nota en el montaje, con algunos tramos que no cierran bien.', 'media'),
  (24122, 'Catherine Zeta-Jones hace de madre separada que arranca de nuevo en Nueva York y se engancha con un chico bastante más joven. Es una comedia romántica con la diferencia de edad invertida al cliché habitual del género. No busca incomodar, busca la fórmula de siempre con los roles cambiados.', 'Si ya viste varias comedias románticas con diferencia de edad invertida, acá no hay vuelta de tuerca que sorprenda.', 'fondo'),
  (268531, 'Es animación de humor bien tonto y físico, pensada para que los chicos se rían de chistes de pedos y nombres ridículos sin culpa. El estilo visual imita a propósito el dibujo de cuaderno de los protagonistas, con secciones hechas como historieta casera. Para adultos sin chicos cerca, el humor se agota rápido.', 'Los gags de pedos y los cortes estilo historieta se repiten seguido, un adulto se cansa antes que los chicos.', 'fondo'),
  (39833, 'Es el debut actoral de Elvis Presley, pensado sobre todo para mostrarlo cantar cuatro temas en medio de un western de posguerra. El triángulo entre los hermanos y la misma mujer es la excusa para llegar a las canciones.', 'Si vas buscando un western serio, la trama queda en segundo plano frente a los números musicales de Elvis.', 'media'),
  (39486, 'Es una película de Disney sobre el caballo que ganó la Triple Corona en 1973, contada desde el punto de vista de la dueña, no del jinete. El foco está en una mujer que no sabía nada de carreras y tuvo que aprender rápido, más que en el caballo mismo. Funciona bien para ver en familia, con ese tono de triunfo inspirador típico de Disney.', 'Si no te gustan los dramas deportivos de fórmula clásica, esta no se aparta mucho de esa estructura.', 'media'),
  (14008, 'Es una comedia de Disney Channel con Hilary Duff como la típica adolescente moderna forzada a una academia militar. El choque de personalidades con la cadete estricta es el motor de casi toda la trama. Funciona para un público pre-adolescente, sin mucha ambición más allá de eso.', 'Si no es tu franja de edad, el humor es bastante básico y predecible.', 'fondo'),
  (475, 'Arthur Penn mezcla glamour criminal con violencia gráfica, algo que en 1967 todavía no se veía en el cine de Hollywood. Warren Beatty y Faye Dunaway tienen una química que convierte a dos asesinos en símbolos pop. Sirve para entender de dónde viene medio cine de atracadores que vino después.', 'El tono cambia bruscamente entre la comedia liviana y la violencia extrema, y eso puede descolocar a quien espera un policial clásico.', 'media'),
  (13483, 'Toma un miedo médico real, la conciencia despierta durante una cirugía, y lo usa como motor de un thriller de traición. Hayden Christensen transmite bien el pánico de estar paralizado y consciente a la vez. Es más efectiva en la premisa que en el desarrollo posterior de la trama.', 'Después del planteo inicial, la historia se vuelve más previsible de lo que promete el arranque.', 'media'),
  (4421, 'Demi Moore hace de la primera mujer en pasar el entrenamiento de una unidad de élite, mientras una senadora usa el caso con fines políticos. Ridley Scott filma el entrenamiento físico con una dureza que no le baja el tono a Moore por ser mujer. Es más sobre resistencia física y presión institucional que sobre un gran mensaje explícito.', 'El entrenamiento militar ocupa gran parte del metraje, y si no te interesa ese tipo de escenas se hace repetitivo.', 'media'),
  (1429, 'Spike Lee filma Nueva York post 11-S como telón de fondo de un hombre que tiene 24 horas antes de entrar en prisión. Edward Norton lleva el peso de la película con una angustia contenida, sin golpes bajos. Es más sobre el duelo por una vida que se termina que sobre el delito en sí.', 'El ritmo es pausado y reflexivo, no esperes tensión de thriller carcelario.', 'media'),
  (1086747, 'Ishana Night Shyamalan debuta con un terror de atmósfera, apoyado en el folclore irlandés más que en sustos de golpe. Dakota Fanning sostiene el misterio de ese grupo encerrado que se observa entre sí noche tras noche.', 'El misterio central se resuelve con una explicación que a varios resultó menos interesante que el planteo.', 'media'),
  (10569, 'Es Woody Allen en modo liviano, lejos de sus dramas neuróticos habituales. La gracia está en ver un plan "perfecto" desarmarse por pura torpeza de los personajes, no por mala suerte. Funciona bien para una noche sin pretensiones.', 'Si buscás el Woody Allen más filosófico o romántico, esta comedia física te va a parecer menor.', 'media'),
  (26171, 'Es el remake americano de una película italiana de Tornatore, con Robert De Niro como un padre viudo que viaja a visitar a sus hijos adultos. Cada parada del viaje revela que la familia que él imaginaba no coincide con la real. Es un drama tranquilo sobre la distancia entre padres e hijos.', 'El tono es bastante más triste de lo que el afiche familiar sugiere.', 'media'),
  (1110358, 'Es la última rareza de Quentin Dupieux, el director de El neumático asesino, y dura apenas una hora y siete minutos. Un espectador se levanta en medio de una obra de teatro mala y decide dirigir la función desde su butaca. Es una comedia incómoda sobre el control y el mal arte, no una comedia de chistes fáciles.', 'Si no te gustó el humor absurdo y seco de Dupieux en otras películas, esta tampoco te va a convencer.', 'alta'),
  (4351, 'Toma un tema real y durísimo, los femicidios de Ciudad Juárez, y lo arma como thriller periodístico con Jennifer López de corresponsal extranjera. Es más efectiva como denuncia social que como suspenso puro. Para quien le interesa el trasfondo antes que la trama policial en sí.', 'El enfoque desde la mirada de la periodista estadounidense deja en segundo plano a las víctimas reales del caso.', 'media'),
  (531509, 'Es una comedia de Netflix sobre tres madres que se sienten dejadas de lado por sus hijos adultos y se plantan en Nueva York a reclamar atención. El tono es liviano y el conflicto generacional se resuelve sin demasiado drama real. Funciona como entretenimiento de tarde de domingo, no busca profundidad.', 'Si buscás un retrato más crudo del vínculo madre-hijo adulto, esto se queda en la superficie.', 'fondo'),
  (774825, 'Es un spin-off corto centrado en Buck, la comadreja tuerta que siempre fue el personaje más excéntrico de la saga. Acá tiene protagonismo total, con las mismas peleas con dinosaurios y los mismos chistes físicos de siempre. Está pensada para chicos que ya conocen a los personajes, no para ampliar la historia de la franquicia.', 'Si no te cae bien el humor exagerado de Buck en las películas anteriores, acá lo tenés en dosis todavía más concentrada.', 'fondo'),
  (454983, 'Es una comedia romántica adolescente de Netflix, pensada para pasar el rato sin exigencias. Sigue los códigos típicos del género: el chico popular, el mejor amigo y el triángulo que se complica.', 'Si buscás algo distinto a los clichés del romance adolescente, esta no te lo va a dar.', 'fondo'),
  (511809, 'Spielberg filma de nuevo el musical de Romeo y Julieta entre pandillas neoyorquinas de los años cincuenta. Los números de baile están coreografiados con una ambición pocas veces vista en el género. La fotografía y el sonido están pensados para pantalla grande.', 'Si ya conocés bien la versión de 1961, esta respeta tanto la estructura que las sorpresas son mínimas.', 'media'),
  (14728, 'Noah Wyle vuelve como el bibliotecario aventurero, esta vez contra vampiros en los pantanos de Nueva Orleans buscando el cáliz de Judas. Es la tercera de una saga de TV movies de tono liviano, a medio camino entre Indiana Jones y la serie B. Funciona para quien ya sigue la saga, no para descubrirla acá.', 'La producción es claramente de TV movie, los efectos y el presupuesto se notan todo el tiempo.', 'fondo'),
  (886396, 'Es una película animada centrada en los hijos de Batman y Superman, pensada para un público más chico. Jon Kent descubre sus poderes y eso lleva a Damian Wayne y a él a convertirse en un nuevo dúo de héroes. Funciona como puerta de entrada a DC para pre-adolescentes, no como una historia pensada para fans adultos.', 'Si venís de las películas animadas de Batman más oscuras, el tono acá es mucho más liviano y pensado para chicos.', 'media'),
  (10414, 'Emilio Estevez hace del abogado forzado a entrenar a un equipo de hockey infantil, la típica historia de redención por el deporte. Los pibes del equipo tienen más personalidad que el relleno habitual de este tipo de películas. Es la clase de comedia familiar que funciona en cualquier década.', 'Si el hockey no te interesa en lo más mínimo, hay bastante tiempo de partido en pantalla.', 'fondo'),
  (437108, 'Está basada en una leyenda coreana real sobre una criatura de montaña que imita voces para atraer a la gente. La película se apoya en el sonido para generar inquietud, más terror de atmósfera que de sustos. El duelo de una madre que perdió a su hijo es el motor emocional de toda la historia.', 'El tramo del medio baja el ritmo para armar el misterio familiar antes de los sustos finales.', 'media'),
  (12227, 'Es una adaptación familiar de Jack London, con la fiebre del oro en Alaska como escenario y el vínculo con el lobo-perro como centro emocional. Ethan Hawke, joven todavía, lleva una historia de aventura clásica sin vueltas de guion complicadas. Funciona bien para ver en familia, con chicos que ya pueden bancarse algo de dureza en la naturaleza.', 'Hay escenas de peleas entre animales que pueden impactar a los chicos más chicos.', 'fondo'),
  (1440, 'Todd Field dirige este drama suburbano donde el romance entre dos vecinos aburridos convive con la amenaza de un pedófilo que volvió al barrio. Kate Winslet está en uno de sus mejores papeles de esa época. Es un drama incómodo que no juzga fácil a ninguno de sus personajes.', 'El tema del pedófilo en el barrio puede resultar pesado para quien busca solo el romance central.', 'alta'),
  (119569, 'Es uno de los cortos "One-Shot" de Marvel, pensado como extra de Blu-ray más que como película independiente. Sigue a una pareja estilo Bonnie and Clyde usando tecnología alien robada, con dos agentes de S.H.I.E.L.D. de por medio. Dura doce minutos, así que es más una curiosidad para fans que una historia completa.', 'Dura solo doce minutos y no tiene desarrollo más allá del gag central.', 'fondo'),
  (214096, 'Toni Collette hace de periodista de rock que tiene que rastrear a un ex novio músico dado por desaparecido. La premisa recuerda al mito real de Elliott Smith. Es más un retrato de ella que una road movie de misterio.', 'Si esperás una investigación con ritmo de thriller, acá el foco está en el personaje y no en el suspenso.', 'media'),
  (976, 'El diálogo filoso escrito por Clifford Odets es el verdadero protagonista, más que cualquier giro de trama. Burt Lancaster hace de columnista que maneja Nueva York desde la mesa de un restaurante, Tony Curtis de publicista dispuesto a cualquier cosa. Es cine clásico en blanco y negro para quien disfruta el cinismo bien escrito.', 'El diálogo es rápido y está cargado de referencias de época, cuesta entrar si no estás acostumbrado a ese ritmo.', 'alta'),
  (828900, 'Mantiene el humor sin lógica de la serie original: chistes que no buscan tener sentido, solo sorprender. Es puro ruido de Adult Swim, no busques trama real detrás. Funciona mejor si ya conocés a estos personajes de antes.', 'Si no conocés la serie original, se siente como entrar a una fiesta ajena a mitad de evento.', 'fondo'),
  (5549, 'Sigue directo después de la primera, con Detroit todavía más hundida en el caos y una nueva droga como problema central. Robocop pierde protagonismo frente a un villano infantil poseído por la tecnología, una decisión rara que divide a los fans. Tiene la sátira ácida de la saga pero con menos control que la original.', 'Si venís de la primera esperando ese mismo filo satírico, esta se siente más desprolija.', 'media'),
  (232572, 'Robert Redford y Nick Nolte hacen de dos amigos grandes que se largan a caminar el sendero de los Apalaches. Basada en las memorias de Bill Bryson, el humor sale del contraste entre la ambición del viaje y los cuerpos que ya no están para eso. Es más comedia de amistad que película de aventura real.', 'Si buscás paisajes como protagonistas, acá el foco está en los diálogos entre los dos amigos, no en el trekking.', 'media'),
  (9563, 'Oliver Stone mete toda su edición frenética y su cámara inquieta en un drama sobre un equipo de fútbol americano en decadencia. Al Pacino hace de entrenador viejo que ya no entiende el negocio en el que se convirtió su deporte. Es más sobre el negocio y el cuerpo que se rompe que sobre ganar partidos.', 'Dura 162 minutos y el montaje nervioso de Stone puede cansar si no te acostumbrás rápido.', 'alta'),
  (1682, 'Es de las entregas clásicas de Godzilla donde el monstruo real es la codicia humana: un empresario quiere explotar el huevo de Mothra sin importarle las consecuencias. Las batallas tienen el encanto de los trajes de goma de la época, sin pretender otra cosa. Para quien disfruta el kaiju clásico de Toho más que el Godzilla de efectos digitales.', 'Los primeros tramos se enfocan en el conflicto humano por el huevo y tardan en largar la pelea entre monstruos.', 'media'),
  (58431, 'Toma el texto de Jane Austen casi literal y le mete zombis de fondo, con las hermanas Bennet entrenadas para pelear además de buscar marido. La gracia está en lo serio que se toma la mezcla, sin guiños ni parodia barata. Funciona mejor si ya conocés la novela y podés ver qué le cambiaron.', 'Si no te interesa Jane Austen, la parte romántica se puede hacer larga entre pelea y pelea.', 'media'),
  (67, 'Abu-Assad sigue a dos amigos de toda la vida en las horas antes de un atentado suicida. No hay bajada de línea fácil sobre lo que están haciendo. La última noche con sus familias, en la que no pueden despedirse, es donde la película pone más peso emocional que en la acción misma.', 'Si buscás una postura política clara a favor o en contra, la película se va a sentir esquiva a propósito.', 'alta'),
  (77621, 'Es la película más antigua que se conserva dirigida por un afroamericano, hecha en parte como respuesta directa a El nacimiento de una nación. Oscar Micheaux no esquiva la violencia racial: incluye un linchamiento de manera frontal, algo que casi ningún estudio de Hollywood mostraba en 1920. Importa más por lo que dice y por quién la hizo que por su pulso narrativo.', 'La trama mezcla varias subtramas, desde el financiamiento de una escuela hasta un lío de gánsteres, y se siente dispersa.', 'alta'),
  (576156, 'Issa Rae y Kumail Nanjiani hacen de pareja a punto de separarse que termina perseguida toda una noche por un crimen que no cometieron. La comedia sale de cómo discuten la relación en medio de la persecución, no de gags sueltos. Funciona si te gusta la comedia de pareja con ritmo rápido y diálogo filoso.', 'Si buscás una trama de crimen que se sostenga en la lógica, la escalada de situaciones absurdas te va a sacar afuera.', 'media'),
  (12102, 'Dustin Hoffman hace de un padre que nunca se ocupó de nada en la casa y de golpe tiene que criar solo a su hijo. La película no toma partido entre los padres, algo poco común para la época en que se hizo. Meryl Streep aparece poco en pantalla pero su presencia pesa en toda la trama.', 'El ritmo es lento y centrado en diálogos domésticos, no esperes grandes giros.', 'media'),
  (429417, 'Viene de una obra de teatro británica de culto, y se nota en cómo cada historia se arma como un acto bien cerrado. El terror es más atmosférico que de sustos fáciles, construido con mucho silencio. Funciona para quien prefiere la inquietud lenta antes que el golpe de efecto.', 'Si buscás sustos constantes, el ritmo pausado de cada relato puede sentirse largo.', 'media'),
  (15413, 'Es una comedia ochentosa sobre el caos doméstico sin adultos a cargo, con Christina Applegate manejando la casa a los 17 con total desparpajo. Funciona por el ritmo liviano y la lógica absurda de los chicos tapando la muerte de la niñera. Buena para ver en familia o de nostalgia noventera.', 'Si no te copa la estética y los chistes de oficina ochentosos, la trama de la agencia de moda se siente añeja.', 'fondo'),
  (274857, 'Guy Ritchie traslada su estilo de películas de atracos londinenses a la leyenda del Rey Arturo. El resultado es una fantasía medieval con diálogos rápidos y un montaje acelerado, más parecida a un policial callejero que a un cuento de caballeros.', 'El montaje fragmentado y los saltos de tiempo cuesta seguirlos si te distraés un segundo.', 'alta'),
  (1228710, 'Es la continuación en cine de la serie, con el mismo tono de western espacial que encontró Favreau en Disney+. Para quien siguió el show, es ver crecer en pantalla grande el vínculo entre Din Djarin y Grogu.', 'Si no viste la serie, entrás sin el vínculo emocional que sostiene la película.', 'media'),
  (33560, 'Es la primera de la trilogía del apocalipsis adolescente de Gregg Araki, con un estilo crudo y de bajo presupuesto típico del cine queer independiente de los 90. Mezcla humor seco con un fondo bastante desesperanzado sobre pibes gays y lesbianas echados de sus casas. El tono cambia de la comedia al desánimo real sin aviso previo, algo marca registrada de Araki.', 'Toca el suicidio de forma directa, así que no es la comedia liviana que el tono inicial promete.', 'media'),
  (10208, 'Le da por una vez el protagonismo a Gonzo, el personaje más raro de la troupe, y arma todo el chiste alrededor de esa rareza. Mantiene el humor absurdo y los cameos marca registrada de los Muppets. Para fans de la serie o quien busque comedia familiar sin maldad.', 'Es la más floja en canciones de las películas clásicas de los Muppets de los 90.', 'fondo'),
  (13499, 'Remake de la comedia de los setenta sobre una pareja que se casa juntando dieciocho hijos entre los dos. El caos doméstico entre dos familias con crianzas opuestas es el motor cómico. Dennis Quaid y Rene Russo llevan el tono liviano sin complicarse.', 'Si ya viste la original de los setenta, esta versión no aporta nada que no supieras.', 'fondo'),
  (42630, 'Sinatra retoma al detective Tony Rome en un policial de Miami con ese tono cool y cínico típico del género. El atractivo es ver a Sinatra en modo duro, no la solidez del misterio.', 'La trama policial es bastante olvidable: el interés está en el estilo, no en el misterio.', 'media'),
  (457799, 'Zac Efron interpreta a Ted Bundy desde la mirada de su novia, que se negó a creer lo que pasaba frente a sus ojos. La elección de punto de vista cambia el tono habitual de este tipo de historias.', 'Al narrar todo desde la negación de la novia, no muestra los crímenes con el morbo que buscan los fans del true crime.', 'media'),
  (179, 'Sydney Pollack arma un thriller político clásico, de los que ya casi no se hacen, con diálogo cuidado en vez de persecuciones. Nicole Kidman y Sean Penn sostienen casi todo el peso en escenas de a dos. Es la primera película filmada con permiso dentro de la sede de la ONU, y eso le da una textura real poco común.', 'El ritmo es pausado y pide paciencia si buscás un thriller más acelerado.', 'media'),
  (48303, 'Kiarostami juega todo el tiempo con la ambigüedad de si James y la galerista son desconocidos o una pareja real fingiendo no conocerse. La película no resuelve esa duda, y ahí está el interés: ver cómo cambia la actuación de ambos según qué versión creas. Es cine para pensar el vínculo entre arte y verdad, no una trama convencional.', 'Si necesitás que la trama te diga qué es real y qué no, esta película no te lo va a aclarar nunca.', 'alta'),
  (9791, 'Buscemi dirige esto con la mirada de quien conoce el mundo carcelario de primera mano. El guion es de Eddie Bunker, que estuvo preso de verdad. Willem Dafoe construye a un preso veterano que protege a Furlong sin que quede claro qué espera a cambio.', 'El ritmo es pausado y hay poca acción para lo que promete el afiche de película carcelaria.', 'media'),
  (33408, 'Es el debut de Alicia Silverstone, un año antes de Clueless, acá en un registro bien distinto. Cary Elwes alquila una habitación en una casa donde la hija de los dueños desarrolla una obsesión peligrosa por él. Es un thriller de acoso adolescente con tono bien noventero.', 'La protagonista tiene 14 años en la ficción, el enfoque sexualizado del personaje envejeció muy mal.', 'media'),
  (820609, 'Casi no hay diálogo en toda la película: Kaitlyn Dever lleva el peso actoral solo con el cuerpo y la cara. La decisión de no explicar el pasado de su personaje hasta bien entrada la trama genera una tensión más emocional que de terror puro.', 'Si necesitás diálogo para enganchar con una película, el silencio constante puede cansar.', 'media'),
  (10731, 'Grisham otra vez, pero acá el centro es un chico de once años manejando presión de fiscales y mafia por igual. Susan Sarandon construye una abogada que no tiene todas las respuestas, lo que la hace más creíble que la heroína típica del género. Es un thriller legal clásico de los 90, sólido sin ser revolucionario.', 'El ritmo es más pausado que el de un thriller actual, con tramos de diálogo legal extenso.', 'media'),
  (44381, 'Es una producción australiana de los noventa con animales reales entrenados, no animación, así que el humor sale de las reacciones físicas del cachorro. Funciona bien para mirar con chicos chicos, sin vueltas de trama.', 'Si buscás algo con ritmo ágil, es una película pensada para un público bien infantil y el avance es lento.', 'fondo'),
  (14527, 'Es una comedia de robos canadiense con Ryan Reynolds todavía lejos de su estrellato actual, con el humor desprolijo típico de sus primeros papeles. La premisa de ladrones teóricos obligados a robar de verdad tiene algo de capricho adolescente.', 'Si esperás un heist prolijo al estilo Ocean''s Eleven, el tono desprolijo y el presupuesto bajo se notan.', 'media'),
  (114779, 'Es una comedia negra de cuatro parejas encerradas que usan el fin del mundo como excusa para sacar a la luz sus miserias. El humor es incómodo y verborrágico, al estilo mumblecore con toque apocalíptico.', 'Si no te gusta el diálogo atropellado y los personajes insoportables a propósito, la premisa te va a cansar rápido.', 'alta'),
  (653729, 'Es un documental filmado con material propio de la familia durante casi veinte años. Sigue a Fox Rich en su lucha para liberar a su marido de la cárcel. Está editado en blanco y negro y mezcla los años sin avisar, así que el tiempo se siente fragmentado a propósito.', 'Salta entre años sin marcarlo con claridad, y si no prestás atención perdés de qué momento de la historia familiar se está hablando.', 'alta'),
  (81440, 'Es la película navideña del ciclo ''Buena Suerte, Charlie'' de Disney Channel, pensada para el público que ya sigue a la familia Duncan en la serie. El viaje frustrado funciona como excusa para juntar a todos los personajes en Navidad. No busca nada más que entretener a los chicos que ya conocen a los protagonistas.', 'Si no viste la serie antes, los chistes sobre la dinámica familiar pierden gracia.', 'fondo'),
  (638974, 'Es la continuación directa de la primera entrega y repite la fórmula de pareja de turistas enredada en un crimen de alta sociedad. Sandler y Aniston tienen buena onda en pantalla y el ritmo no da tiempo a aburrirse. Sirve para una noche sin pretensiones, no para buscar un misterio bien armado.', 'El misterio es una excusa: si buscás un enigma que cierre prolijo, te vas a quedar con gusto a poco.', 'media'),
  (605116, 'La pastilla funciona como lotería de superpoderes, y la incertidumbre de qué va a pasar en cada toma es el motor de la película. Jamie Foxx y Joseph Gordon-Levitt llevan el costado policial mientras Dominique Fishback aporta la mirada más callejera.', 'El tercer acto se vuelve más genérico de lo que prometía la idea inicial.', 'media'),
  (38718, 'Jeremy Irons construye a Claus von Bülow como un enigma total, sin que la película se juegue nunca por si es inocente o culpable. La narración de la esposa en coma le da un tono entre mordaz y macabro poco habitual en el drama judicial. Para quien disfruta la ambigüedad moral más que un veredicto claro.', 'Si buscás una resolución clara sobre la culpabilidad, la película se niega a dártela.', 'alta'),
  (31682, 'Scott Carey se encoge poco a poco hasta que su casa se vuelve un territorio hostil, con la araña del sótano como amenaza real. Es ciencia ficción de ideas de los 50, con efectos prácticos de la época. Funciona para quien disfruta el cine clásico de ciencia ficción, no el efecto digital.', 'Hay mucha narración en off explicando el proceso científico, eso corta bastante el ritmo de la aventura.', 'media'),
  (586810, 'Es animación francesa adulta, con un diseño visual denso y una trama de ciencia ficción noir. Mezcla androides, hackers y una detective con un compañero muerto que reencarnó en el cuerpo de un robot. No es para chicos: el tono es más cercano a Blade Runner que a una animación convencional.', 'El primer tramo larga nombres, tecnología y reglas del mundo muy rápido, y si te perdés ahí cuesta reengancharse.', 'alta'),
  (14819, 'Es una comedia noventera de campamento de verano escrita en parte por Judd Apatow, con Ben Stiller como un instructor de fitness obsesivo que se vuelve el villano cómico de la película. El eje no es burlarse de los chicos con sobrepeso sino de la obsesión adulta por la dieta y el ejercicio extremo. Tiene ese humor físico y absurdo típico del Disney de los 90.', 'Si te incomoda el humor sobre el peso y el cuerpo, la premisa del campamento te va a incomodar igual.', 'fondo'),
  (13551, 'La estructura en cinco historias separadas, cada una con su propio elenco, arma el rompecabezas de la víctima desde afuera hacia adentro. Cada segmento cambia de tono y de protagonista, sin un hilo conductor único de principio a fin. Funciona si te interesan los dramas corales más que una investigación policial tradicional.', 'Al cambiar de personajes en cada segmento, cuesta encariñarse con alguno antes de que la historia salte a otro.', 'alta'),
  (529485, 'Ben Affleck hace de un ex jugador alcohólico con una entrega que en su momento se sintió personal. La película evita el arco de redención prolijo del género deportivo: los avances del personaje no son lineales ni garantizados.', 'Si buscás la típica película de equipo que remonta hasta ganar el campeonato, el foco está en otro lado.', 'media'),
  (1497, 'Es la secuela más desprolija y más noventera de la saga, con un cameo musical de Vanilla Ice incluido. Apunta directo a los chicos y no disimula el presupuesto ajustado de los trajes. Sirve para la nostalgia más que para buscar algo sólido en la trama.', 'Los disfraces y los efectos de esta producción puntual envejecieron bastante mal.', 'fondo'),
  (38582, 'Esta de la era Showa suma mitología okinawense con King Caesar, un guardián de piedra que hay que despertar con una canción ritual. La vuelta de tuerca es que los villanos no son monstruos sino extraterrestres disfrazados, y eso cambia el tipo de suspenso. Para fans de la saga clásica más que para alguien que busca su primer Godzilla.', 'Hay bastante trama de espionaje alienígena antes de que aparezcan los monstruos a pelear.', 'media'),
  (11975, 'Matt Damon joven hace de abogado idealista contra una aseguradora, con Coppola dirigiendo el típico thriller legal de Grisham sin lujos de autor. Danny DeVito aporta el cinismo que le falta al protagonista.', 'Si ya viste varias películas de abogados de los noventa, la fórmula se nota bastante.', 'media'),
  (1581, 'Las dos historias corren en paralelo sin cruzarse demasiado, con ritmos bien distintos entre Inglaterra y California. Es una comedia romántica que se disfruta más por la ambientación navideña que por sorpresas de guion.', 'Dura más de dos horas para una comedia romántica, algo que se nota en el tramo final de la historia californiana.', 'fondo'),
  (92620, 'Es una película de Disney Channel sobre el apartheid contada desde la amistad entre dos chicas, basada en una historia real de intercambio estudiantil. Funciona como primer acercamiento al tema para audiencia joven.', 'La película simplifica bastante el contexto político del apartheid para hacerlo digerible a un público adolescente.', 'media'),
  (10735, 'Amanda Bynes lleva la película con un registro físico, de comedia gestual, que compensa lo previsible del argumento. Colin Firth hace de aristócrata rígido con un timing cómico más fino de lo que promete el afiche.', 'Si ya viste varias comedias de padres separados que deben reconciliarse, no hay sorpresas en el camino.', 'fondo'),
  (46705, 'La película corta entre el inicio de la relación y su final sin avisar, armando el contraste vos mismo. Gosling y Williams hacen que ese contraste duela sin necesidad de gritos ni grandes escenas.', 'Es dura emocionalmente de un modo bien realista, sin alivio cómico en el medio.', 'alta'),
  (819876, 'Cronenberg vuelve al body horror después de años filmando dramas más convencionales. Viggo Mortensen y Léa Seydoux hacen de artistas que usan la cirugía como forma de expresión, en un mundo donde el dolor físico desapareció.', 'Las imágenes de cirugías y mutaciones son explícitas y pueden resultar muy fuertes para quien no conoce su estilo.', 'alta'),
  (17927, 'Es una comedia adolescente que invierte el cliché: los chicos populares eligen el campamento de animadoras para estar rodeados de chicas. El chiste se sostiene en esa premisa simple, sin complicarse con subtramas. Entretiene si no le pedís nada más que eso.', 'Si ya viste muchas comedias de campamento adolescente, el humor te va a resultar previsible.', 'fondo'),
  (760161, 'Es la precuela de La huérfana, así que ya sabés el truco detrás del personaje de Leena. La gracia está en ver cómo la actriz lo vuelve a vender, esta vez con otra vuelta de tuerca en la historia.', 'Si no viste la primera La huérfana, buena parte del efecto sorpresa que arma esta precuela se pierde.', 'media'),
  (2666, 'La ciudad entera se reconstruye cada noche mientras los habitantes duermen, sin que lo recuerden. La pregunta de qué es real se instala antes de que el protagonista mismo la haga. Visualmente está muy cerca del expresionismo alemán.', 'El ritmo es pausado para lo que promete el póster de ciencia ficción de acción.', 'alta'),
  (1115191, 'Repasa casos reales de intoxicaciones masivas en EE.UU., como el brote de E. coli de Jack in the Box en 1993. El abogado Bill Marler aparece como hilo conductor entre casos distintos. Sirve para entender cómo funciona, y falla, el sistema de seguridad alimentaria.', 'Salta entre varios casos sin profundizar en ninguno, así que algunos tramos se sienten repetitivos.', 'media'),
  (25694, 'Es la versión de Paramount con un elenco de estrellas de época disfrazadas hasta quedar irreconocibles, entre ellas Cary Grant y Gary Cooper. El atractivo está en reconocer a los actores bajo el maquillaje, más que en la historia.', 'Los efectos y el ritmo envejecieron bastante mal frente a versiones posteriores de la misma historia.', 'media'),
  (331354, 'La escribió, dirigió y protagonizó Leticia Dolera, que se llevó varios premios por esta película, incluido reconocimiento como nueva directora. Es comedia con fondo bastante amargo: ansiedad, precariedad laboral, la presión social de tener la vida resuelta a los 30. Funciona para quien busca comedia española con un costado más incómodo que liviano.', 'El tono mezcla comedia con ansiedad real, así que no es la comedia ligera que puede parecer por el afiche.', 'media'),
  (619778, 'James Wan arranca con pesadillas, parálisis y terror sobrenatural clásico, y termina yendo a un lugar que no es el esperable. Annabelle Wallis carga casi sola la primera mitad, con mucho primer plano y poca explicación.', 'Si preferís terror de un solo registro de principio a fin, esta cambia de tono a mitad de camino.', 'media'),
  (228970, 'Reese Witherspoon camina sola con la mochila como columna vertebral de toda la película. Los flashbacks van llenando por qué está ahí sin que se sienta forzado. Es más sobre el duelo y la relación con la madre que sobre la proeza física.', 'Si buscás una de aventura con peligro constante, el ritmo es más interno y contemplativo que de supervivencia.', 'media'),
  (10539, 'Henry Selick mezcla stop-motion con actores reales, el mismo truco visual que usó en Pesadilla antes de Navidad. Los insectos gigantes tienen diseños inquietantes para ser una película infantil, algo muy de Tim Burton como productor. Funciona bien para chicos que ya vieron otras animaciones y quieren algo un poco más raro.', 'Las escenas con las tías al principio son más oscuras de lo que espera un chico chico.', 'media'),
  (13417, 'Es una producción directa a video, pensada para expandir al personaje secundario más querido de la primera, Kronk. Mantiene el humor absurdo y los chistes meta de la original, aunque con menos filo. Sirve para fans de la primera que quieren más del mismo personaje.', 'La calidad de animación y el guion son notoriamente más flojos que los de la película original.', 'fondo'),
  (9268, 'Schwarzenegger de agente de protección de testigos enfrentado a traficantes de armas, con ese tono de acción noventosa que no se toma en serio. Las escenas de acción, para la época, apostaban fuerte a los efectos digitales.', 'Los efectos que en su momento eran la gran novedad hoy se ven bastante envejecidos.', 'fondo'),
  (5994, 'Nicolas Cage es un ejecutivo de Wall Street que se despierta viviendo la vida que hubiera tenido si elegía el amor y no la carrera. Es la típica fantasía de ''qué hubiera pasado si'', pero con Cage comprometido con el costado más sentimental.', 'Si ya viste varias películas de segundas oportunidades de los 90, la premisa te va a resultar previsible.', 'fondo'),
  (230170, 'Es un show íntimo, grabado para apenas 39 personas en un club chico de Los Ángeles. Silverman mezcla humor absurdo con bits personales, sin la escala de sus especiales más grandes.', 'Si buscás un show con bajada política fuerte, este se mueve más en lo personal y lo absurdo.', 'fondo'),
  (894205, 'Es un especial de Marvel pensado como corto de terror clásico, filmado en blanco y negro. Tiene el aire de las películas de monstruos clásicas de Universal y dura menos de una hora. Funciona bien para quien busca terror de monstruos sin comprometerse a toda una saga de superhéroes.', 'Dura 55 minutos y se nota: el desarrollo de personajes es mínimo porque todo está puesto al servicio del ritmo.', 'media'),
  (20771, 'Es el cierre de la serie de Disney Channel, pensado para quien siguió a Kim Possible y quiere ver resuelta la tensión con Ron. No busca sorprender, busca cerrar bien la historia que ya conocés.', 'Si nunca viste la serie, la relación entre Kim y Ron no te va a generar nada.', 'fondo'),
  (406990, 'El truco central es una sola actriz haciendo de siete hermanas distintas. Cada una tiene su propio gesto y su propia velocidad, no solo el peinado o la ropa. También funciona como ciencia ficción política además de thriller.', 'Cuesta al principio distinguir a las siete hermanas hasta que el ojo se acostumbra a los gestos de cada una.', 'alta'),
  (18126, 'Miley Cyrus deja por un rato las luces de Hollywood para volver al pueblo de su familia. Es una película pensada de punta a punta para el público de la serie. Tiene números musicales y el tono liviano típico de Disney Channel de esos años.', 'Si no seguiste la serie o no tenés nostalgia por ella, la historia no tiene mucho más para ofrecer.', 'fondo'),
  (471498, 'Mélanie Laurent actúa casi sola, encerrada en una cápsula. El suspenso se construye a partir de lo que ella misma no sabe de su propia historia. Aja filma el encierro sin recurrir al sustito fácil, apostando a la angustia física del espacio reducido.', 'Si te genera ansiedad real estar encerrado en espacios chicos, la premisa puede resultar pesada.', 'alta'),
  (10781, 'Es la precuela que cuenta cómo Leatherface se convirtió en el asesino de la familia Sawyer, con Vietnam como telón de fondo social. Apuesta por la violencia explícita y el gore más que por el suspenso lento de la original de 1974. Funciona como entretenimiento duro de slasher, sin la ambición de la película que lo originó.', 'Si venís de la original de Tobe Hooper esperando esa misma tensión contenida, esta es mucho más gráfica y directa.', 'media'),
  (472983, 'Es la vuelta de la serie de culto de Nickelodeon en formato película, con el mismo humor ácido y el dibujo filoso de Jhonen Vásquez. Zim y Dib retoman su rivalidad de siempre, ahora con más presupuesto para el caos visual. Le sirve a quien ya conocía la serie; si no la viste, varios chistes no van a aterrizar igual.', 'Si no viste la serie original, varias referencias y chistes internos van a pasar de largo.', 'media'),
  (30131, 'Cantinflas hace un doble papel: el criado bueno y, sin que nadie lo sepa, el hermano gemelo de un bandido temido. La gracia clásica de Cantinflas, esas vueltas verbales sin sentido que se hicieron famosas, está en todo su esplendor. Es cine de oro mexicano puro, con Miguel M. Delgado dirigiendo, su socio habitual en estas comedias.', 'El humor depende mucho de las vueltas verbales típicas de Cantinflas, que pueden costar si no estás acostumbrado a su estilo.', 'media'),
  (938614, 'Toda la película transcurre como la grabación de un programa de entrevistas en vivo de los años 70. Esa estética de video analógico le da un clima propio, casi de objeto encontrado. El terror se construye de a poco, jugando con lo que la cámara del estudio llega a captar.', 'Si no te atrapa el formato de falso programa de televisión en vivo, la estructura puede sentirse encorsetada.', 'alta'),
  (326359, 'Es el corto de ocho minutos donde Anna cumple años y Elsa quiere hacerle una fiesta perfecta, hasta que sus poderes de hielo complican todo. Está pensado como extra para quienes ya vieron Frozen, no como historia independiente. Es puro servicio de fans, liviano y breve.', 'Dura ocho minutos y no tiene una trama propia más allá del festejo de cumpleaños.', 'fondo'),
  (16220, 'Bakshi mezcla dibujos con recortes de noticieros de guerra reales y rotoscopia, un collage que no se parece a nada del fantástico de esa época. Funciona para quien busca una curiosidad under de los setenta, no para quien espera prolijidad estilo Disney.', 'Si esperás una fantasía prolija tipo Disney, la mezcla cruda de técnicas gráficas y metraje bélico real te va a chocar.', 'media'),
  (461130, 'Es ciencia ficción de bajo presupuesto sobre gente con poderes que vive en la pobreza. La premisa funciona más como alegoría de clase que como espectáculo de superhéroes. Los hermanos Amell sostienen la película con oficio.', 'El presupuesto ajustado se nota en las escenas de acción, bastante más chicas que lo que promete la idea.', 'media'),
  (193610, 'La gracia está en que la esposa engañada y la amante deciden ser aliadas en vez de rivales. Cameron Diaz y Leslie Mann tienen buena dinámica de comedia juntas.', 'El tramo de la venganza se estira más de la cuenta hacia el final.', 'fondo'),
  (537116, 'Andrew Garfield se mete en la piel de Jonathan Larson, el compositor de Rent. Son los días en que siente que el tiempo se le escapa antes de triunfar. Lin-Manuel Miranda dirige con cariño de fan, mostrando el proceso creativo desde adentro.', 'Si no conocés nada del mundo del teatro musical de Nueva York, varias referencias y guiños te van a pasar de largo.', 'media'),
  (3036, 'Branagh filma la novela con más fidelidad al texto original que casi cualquier otra adaptación. El monstruo de Robert De Niro es elocuente y sufriente, no un bicho mudo.', 'El estilo actoral es muy exagerado, a tono con el gótico operístico de Branagh.', 'media'),
  (762441, 'Cambia el foco de la familia que sobrevive por reglas hacia una sola persona en el primer día del ataque. Esa persona ya estaba en lo peor de su vida antes de que llegaran los monstruos. Depende más de la actuación de Lupita Nyong''o que de sustos nuevos.', 'Si venís de las dos anteriores esperando más acción con las criaturas, esta es mucho más íntima y lenta.', 'media'),
  (30014, 'Fritz Lang dirige este noir de bajo presupuesto sobre un escritor fracasado que convence a su hermano de tapar un crimen que cometió. Usa una casa victoriana a la orilla del río como escenario casi gótico para la culpa y la paranoia, algo poco típico del noir urbano habitual. Es una de las películas menores de Lang, pero se nota su mano en cómo construye la tensión.', 'El tramo en que el hermano carga con la culpa estira el ritmo del medio de la película.', 'media'),
  (553646, 'Es un documental corto de la serie ReMastered de Netflix, sobre la muerte de Sam Cooke en un motel de Los Ángeles en 1964. Sirve para quien conoce sus canciones pero no su rol en la lucha por los derechos civiles.', 'Plantea la teoría del complot sin aportar pruebas nuevas, así que puede dejarte con más preguntas que respuestas.', 'media'),
  (11135, 'Disney cambia el escenario urbano de la primera por la naturaleza australiana, con un águila como centro del rescate. Tiene una de las secuencias de vuelo más logradas de la animación Disney de esa época, mucho antes de la computadora gráfica. Funciona bien como aventura corta para chicos, sin la carga emocional de la primera.', 'La trama es bastante más simple que la de la primera película, casi un pretexto para la acción.', 'fondo'),
  (656690, 'Exempleados de Facebook, Google y Twitter explican desde adentro cómo están diseñados los algoritmos para captar tu atención el mayor tiempo posible. Mezcla entrevistas con dramatizaciones de una familia afectada por el uso de pantallas.', 'Las partes dramatizadas con actores son bastante más flojas y obvias que las entrevistas documentales.', 'media'),
  (18250, 'Vincent Price vuelve como el villano más elegante del terror setentista, armando muertes rebuscadas con estética egipcia en vez de sustos convencionales. Es más comedia negra extravagante que terror real, pensada para disfrutar el estilo visual y el humor macabro. Pide haber visto El Abominable Doctor Phibes para entender quién es Phibes y por qué hace todo esto.', 'Si buscás terror que asuste, no es lo tuyo: la gracia está en lo recargado y absurdo de cada muerte.', 'media'),
  (625450, 'Ava Michelle hace de la chica más alta del colegio que por fin decide dejar de esconderse. Es una comedia adolescente de Netflix bastante estándar en su fórmula. Funciona para un público joven que busca algo liviano sobre inseguridades físicas.', 'Los conflictos se resuelven de manera bastante simplista para un tema que da para más.', 'fondo'),
  (30974, 'Es un thriller francés también conocido como High Lane, sobre un grupo de amigos que va a escalar una montaña en Croacia. Lo que arranca como aventura con tensiones de pareja de fondo se convierte en una pesadilla de supervivencia. Funciona como terror de montaña físico, sin vueltas sobrenaturales.', 'Si vas con la idea de un drama de amigos escalando, el giro hacia el terror puro puede tomarte por sorpresa.', 'alta'),
  (295592, 'Es un documental de Disneynature narrado por Tina Fey, filmado en ruinas de templos antiguos en Sri Lanka. Sigue a una mona de rango bajo que tiene que abrirse camino en una jerarquía social bastante rígida, casi como una trama de ascenso social. Tiene ese tono family-friendly típico de la marca, con una narración que humaniza mucho a los monos.', 'La narración humaniza tanto a los monos que se siente almibarada si preferís un documental más seco.', 'fondo'),
  (9762, 'La trama es la excusa para llegar a los números de baile, que es donde la película realmente funciona. Channing Tatum todavía no era la estrella de acción que fue después, acá es puro baile de calle.', 'El romance y el conflicto de clases están contados con bastante brocha gruesa.', 'fondo'),
  (287947, 'Tiene menos solemnidad que otras películas de DC: es básicamente un chico de 14 años probando qué hacer con un cuerpo de superhéroe adulto. Funciona bien en familia porque no pide haber visto otras películas del universo DC.', 'El tono liviano se nota en el villano, que queda bastante por debajo del protagonista en interés.', 'media'),
  (9598, 'Un chanchito que quiere ser perro pastor, de esas películas de animales que funcionan tanto para chicos como para adultos sin caer en lo tonto. La voz en off y los animales que hablan le dan un tono propio, entre fábula y comedia.', 'Tiene momentos más tristes de lo que promete el afiche de comedia familiar.', 'fondo'),
  (14254, 'Es el remake americano de la surcoreana Dos hermanas, y mantiene el clima de desconfianza entre hermanas y madrastra que tenía el original. El terror acá es psicológico, con sustos medidos en vez de golpes de efecto constantes. Es buena opción si preferís el misterio familiar al terror de sobresaltos.', 'Si ya viste Dos hermanas, te vas a adelantar a varios giros antes de que la película los revele.', 'media'),
  (775996, 'Anthony Mackie hace de androide militar que entrena a un piloto de drones en una zona de guerra futurista. De fondo está la pregunta de hasta dónde delegarle decisiones a una máquina. Es ciencia ficción de acción de Netflix, con ese dilema como gancho.', 'La resolución del dilema moral queda bastante subordinada a las escenas de acción.', 'media'),
  (37969, 'Es la película original en la que se basó Rescatados (Homeward Bound), pero acá los animales no hablan. Todo se cuenta con una narración más documental, basada en la novela de Sheila Burnford, con un tono calmo y realista. Funciona bien como aventura familiar tranquila, sin chistes ni voces de personajes.', 'Si conocés la versión de los 90 con los animales hablando, acá no hay nada de eso: es puro relato narrado.', 'fondo'),
  (15373, 'Paul Rudd y Seann William Scott hacen de promotores fracasados condenados a hacer de mentores de chicos. La gracia está en que ninguno de los dos quiere estar ahí. El humor es bastante más ácido que el de otras comedias de ''adultos que cuidan niños''.', 'Si no te gusta el humor incómodo o un poco cruel, varias escenas se pasan de rosca.', 'fondo'),
  (481084, 'Pasa a la familia Addams al formato animado manteniendo el humor macabro de los originales, ahora con una trama simple de amenaza inmobiliaria. Oscar Isaac y Charlize Theron le ponen las voces a Gómez y Morticia con gusto evidente. Se sostiene más por el diseño visual gótico que por el guion.', 'La historia es bastante simple y predecible, pensada sobre todo para el público infantil.', 'fondo'),
  (15919, 'Ernest Borgnine juega a un carnicero solterón sin ningún atractivo de galán de Hollywood, y ahí está la fuerza de la película. Es un drama romántico chico, de barrio, sobre la soledad y la presión social de ''sentar cabeza''. Ganó el Oscar a mejor película por esa honestidad sin artificio, no por espectacularidad.', 'Si buscás un romance con vueltas de trama, esto es más bien un retrato íntimo sin grandes sorpresas.', 'media'),
  (55787, 'El circo de la Gran Depresión funciona como escenario de clase, con los animales como otra forma más de propiedad. Robert Pattinson y Reese Witherspoon sostienen un romance clásico de época, sin grandes sorpresas.', 'El ritmo es lento y el romance sigue una fórmula bastante previsible.', 'fondo'),
  (75174, 'Liam Neeson no está salvando a nadie a los golpes, está tratando de sobrevivir al frío y al cansancio antes que nada. Los lobos son menos un enemigo de acción y más una amenaza que nunca se ve del todo.', 'Si fuiste con la expectativa de ver a Neeson peleando lobos como en los avances, la película es mucho más contemplativa.', 'media'),
  (522887, 'Es animación europea, con un diseño de personajes bastante más simple que el de las grandes productoras de Hollywood. La historia de identidad entre gaviotas se banca bien con chicos chicos.', 'El ritmo es más pausado que el de la animación de gran presupuesto, así que a los chicos impacientes les puede costar.', 'fondo'),
  (37635, 'Es noir clásico con Barbara Stanwyck como testigo a la que nadie le cree, un armado típico del género de los años 50. La tensión está en la desconfianza hacia ella, no en sorpresas de guion.', 'El ritmo es lento para el suspenso actual: pesa más el diálogo que la persecución.', 'media'),
  (744857, 'Rugna construye el horror a partir de la lógica rural argentina: nadie quiere hacerse cargo del problema. Esa pasividad es la que deja que todo termine pudriéndose del todo. No hay sustos tradicionales, hay una sensación de deterioro constante que no da respiro.', 'Tiene escenas de violencia hacia animales y chicos bastante más duras de lo que el afiche sugiere.', 'alta'),
  (303623, 'Es el cierre de la serie de HBO que cancelaron después de una sola temporada, armado para darle un final a Stuart y sus líos amorosos. El humor mantiene el bochorno marca Stephen Merchant, en la línea de The Office pero con un protagonista todavía más patético. Tiene más sentido si ya seguiste la temporada que si entrás de cero.', 'Pide haber visto la temporada: los chistes y las relaciones entre personajes vienen armados desde ahí.', 'media'),
  (512, 'Es Woody Allen en modo liviano, más cerca de la comedia de enredos que del drama existencial de sus películas más conocidas. Scarlett Johansson y el propio Allen tienen una química de nerd torpe y aprendiz entusiasta que sostiene toda la trama.', 'Si esperás su humor más filosófico, acá se queda en la superficie de la trama policial.', 'media'),
  (324670, 'Un escuadrón de operaciones especiales se topa con criaturas que solo se ven con cámaras térmicas. Ese truco visual es lo más interesante de la película. Es ciencia ficción militar de Netflix, prolija pero sin demasiadas pretensiones.', 'Los personajes están poco desarrollados, así que si buscás algo más que la premisa visual te vas a quedar corto.', 'media'),
  (83552, 'Jafar Panahi tenía prohibido hacer películas por el gobierno iraní, así que esto es técnicamente no una película. Es un registro de un día encerrado en su departamento esperando la apelación de su condena, sacado de Irán escondido en una torta adentro de un pendrive. Es un acto de desobediencia filmado casi en tiempo real, más que un documental convencional.', 'Buena parte es Panahi dando vueltas por su departamento en tiempo real, así que pide paciencia si buscás más acción.', 'alta'),
  (575446, 'Es la película de Michel Franco que ganó el Gran Premio del Jurado en Venecia. Un estallido social interrumpe una boda de la clase alta mexicana y todo se desarma en minutos. Es dura y no da respiro: funciona para quien busca cine político incómodo, no para una noche liviana.', 'Es bastante más violenta y asfixiante de lo que promete el arranque de boda, sobre todo en su segunda mitad.', 'alta'),
  (913862, 'Es un documental de Netflix sobre los dos accidentes del 737 MAX. Muestra cómo Boeing priorizó el cronograma de producción por sobre las alertas de seguridad de sus propios ingenieros. Funciona para quien quiere entender la mecánica corporativa detrás de la tragedia, no solo el hecho en sí.', 'Maneja bastante información técnica sobre aviación y proceso regulatorio, así que pide prestar atención para no perder el hilo.', 'alta'),
  (9272, 'Macaulay Culkin usa la cara de Home Alone para interpretar a un chico profundamente perturbado, y ese contraste es todo el gancho de la película. Elijah Wood hace del primo que empieza a notar que algo anda mal. Es un thriller psicológico con niños en el centro, bastante más oscuro de lo que parece.', 'Ver a Macaulay Culkin en un papel tan oscuro puede resultar perturbador para quien lo recuerda solo de Mi pobre angelito.', 'media'),
  (18269, 'Es la secuela directa a video de La dama y el vagabundo, centrada en el hijo rebelde de la pareja original. Tiene la estructura clásica de esas secuelas Disney: menos elaborada que la original, pero con canciones y el mismo tono familiar. Funciona bien para chicos que ya quieren saber qué pasó después de la primera película.', 'Si esperás el nivel de animación y música de la película original de 1955, esta secuela se siente notoriamente más simple.', 'fondo'),
  (9882, 'La película imaginó la ley marcial en Nueva York por atentados terroristas, años antes del 11 de septiembre. Esa anticipación es lo que la vuelve interesante hoy, más que su forma de thriller político convencional.', 'El trato de la comunidad árabe-americana es de su época y hoy se lee con otra sensibilidad.', 'alta'),
  (1272, 'Danny Boyle filma el espacio como un lugar que puede quemarte, enceguecerte o desintegrarte sin aviso. La tripulación empieza a quebrarse por el encierro y la presión de la misión, no solo por el peligro externo. Es ciencia ficción que se apoya en la física y el desgaste psicológico.', 'Si buscás una de acción espacial rápida, los primeros tramos son bastante técnicos y contemplativos.', 'alta'),
  (6278, 'Dragones apocalípticos en una Inglaterra devastada, con Christian Bale de líder reacio y Matthew McConaughey como cazador de dragones excesivo. Funciona como cine de acción ochentoso con criaturas, sin pretensiones de prestigio.', 'Los efectos especiales ya muestran el paso del tiempo, así que si buscás dragones hiperrealistas vas a notar las costuras.', 'media'),
  (489430, 'Terror argentino filmado en el conurbano bonaerense, con un grupo de investigadores que encara fenómenos paranormales sin golpes de efecto importados. Demian Rugna construye el miedo con sonido y fuera de campo, más que con sustos fáciles. Tuvo repercusión afuera: Guillermo del Toro la recomendó públicamente.', 'Al ser varios casos encadenados, no todos los segmentos de terror pegan con la misma fuerza.', 'alta'),
  (229749, 'Es la primera película de la saga ''When Calls the Heart'', con el tono buena onda y sin sobresaltos típico de Hallmark. Sigue a una maestra que se adapta a un pueblo rural del oeste americano.', 'Si ya viste otras producciones Hallmark, la fórmula te va a resultar muy conocida.', 'fondo'),
  (14317, 'Es la versión cine de la serie de Nickelodeon, con la misma familia aventurera y el mismo humor de siempre. Tiene más presupuesto para la animación y suma una trama de cazadores furtivos como hilo central. Funciona bien para quien ya conocía la serie de chico.', 'Si nunca viste la serie, te vas a perder algunas referencias a personajes y chistes recurrentes.', 'media'),
  (7461, 'La gracia está en la estructura: la misma media hora se repite ocho veces, cada vez desde un testigo distinto. El rompecabezas se termina de armar recién cuando se cruzan todas las versiones. Funciona mejor si te entregás al juego de las perspectivas sin pedirle demasiado realismo político.', 'Repite la misma media hora ocho veces antes de mostrar el cuadro completo, y la tercera vuelta ya se siente repetitiva.', 'alta'),
  (396806, 'Niccol imagina una vigilancia tan total que nadie usa pantallas: todo lo que la gente ve queda grabado directo en los ojos. Clive Owen hace de detective agotado, no de héroe de acción. Esa decisión le da a toda la historia un tono de policial frío y pausado.', 'Si buscás acción, la historia se mueve al ritmo pausado de un policial cerebral.', 'alta'),
  (82, 'Michael Mann traslada la serie de los 80 a un tono mucho más árido y realista. Colin Farrell y Jamie Foxx son los encubiertos que terminan metidos en una operación que se les escapa de las manos. La estética digital y nocturna de Mann pesa tanto como la trama.', 'Si vas buscando el neón y la onda pop de la serie original, esta versión es fría y seria.', 'alta'),
  (320007, 'Está filmada en un solo plano continuo de más de dos horas, sin cortes. La cámara persigue a la protagonista en tiempo real mientras la noche se le complica cada vez más. Laia Costa sostiene toda la película con una energía que no decae nunca.', 'El primer tramo, antes de que arranque el quilombo real, se toma su tiempo en armar el grupo.', 'alta'),
  (376866, 'Natalie Portman reconstruye el duelo de Jackie Kennedy minuto a minuto, entre el protocolo de Estado y el shock personal. Pablo Larraín filma el instante en que una mujer decide cómo va a ser recordado su marido, no la política detrás.', 'Si esperás un relato cronológico de la presidencia de Kennedy, no es eso: la película se queda pegada a esas pocas jornadas.', 'alta'),
  (203801, 'Guy Ritchie filma la Guerra Fría como un desfile de trajes y chicanas visuales, más cerca del estilo que de la tensión de espías real. Cavill y Hammer construyen una rivalidad con humor que sostiene la película.', 'Si buscás una de espías con tensión real, aquí la estética le gana siempre al guion.', 'media'),
  (9946, 'Schwarzenegger se enfrenta literalmente al Anticristo en un Nueva York de fin de milenio, con todo el imaginario apocalíptico que generaba el cambio de siglo. Es acción ochentosa con capa de terror sobrenatural, sin disimular lo pulp que es.', 'Si tomás en serio la mitología religiosa que plantea, no va a aguantar mucho análisis.', 'fondo'),
  (1161108, 'Dupieux arranca como una comedia de enredos en un restorán perdido. A los pocos minutos los personajes empiezan a hablar de que están actuando en una película. A partir de ahí todo es metacine sobre la industria del cine y la inteligencia artificial, con el humor absurdo marca Dupieux.', 'El quiebre de la cuarta pared llega de golpe y corta la comedia de enredos que venía armando.', 'alta'),
  (34205, 'Segunda entrega de la saga de Disney Channel, pensada para público familiar y fans de la primera. Mantiene el tono liviano de brujas buena onda y pueblo mágico, sin buscar asustar en serio. Gana bastante si ya conocés a Marnie y su familia de antes.', 'Es telefilm de Disney Channel de 2001 y se nota en los efectos y el presupuesto.', 'fondo'),
  (800510, 'Soderbergh arma un thriller clásico de alguien que vio algo que no debía ver, pero con pandemia y vigilancia tecnológica como motor. Zoë Kravitz lleva el peso de una protagonista agorafóbica que tiene que salir a la calle para que le crean. Dura menos de 90 minutos y no pierde el tiempo en vueltas.', 'Si no bancás el tema de la paranoia tecnológica pospandemia, el contexto se siente ya atado a su momento.', 'media'),
  (2207, 'Bruce Willis hace de policía alcoholizado y venido abajo al que le tocan dieciséis cuadras para llevar a un testigo al juzgado. La película se arma casi en tiempo real sobre ese trayecto. Es un thriller urbano chico, más sobre la redención del personaje que sobre la acción.', 'El ritmo es más pausado que el de una persecución típica, y si buscás acción constante te puede quedar lento.', 'media'),
  (597316, 'Es un reinicio pensado para una audiencia nueva, con animación en CGI que cambia bastante la estética de las generaciones anteriores. La historia de unir especies separadas por el miedo funciona como metáfora simple para el público infantil. Para quien viene de las generaciones anteriores puede sentirse como otro punto de partida.', 'Si venís de las generaciones anteriores, el cambio a CGI y de tono se siente brusco.', 'fondo'),
  (13691, 'Es de las películas más chicas y tiernas del universo Winnie the Pooh, centrada en la ansiedad de Piglet por sentirse el más pequeño e inútil del grupo. El mensaje sobre el coraje a pesar del miedo está pensado directo para los más chicos, sin dobles lecturas para adultos. Funciona bien de puerta de entrada a los personajes para nenes pequeños.', 'Si tus hijos ya son grandes para Winnie the Pooh, el tono infantil se les va a quedar chico.', 'fondo'),
  (9367, 'Robert Rodriguez filmó esto con siete mil dólares y actores no profesionales, y esa urgencia se nota en cada plano. Es cine de acción hecho a pura necesidad, sin presupuesto para pulir nada. Atrae más por cómo se hizo que por sorpresas en la trama.', 'Las actuaciones y el sonido tienen la rigidez de una producción sin presupuesto.', 'fondo'),
  (376290, 'Jessica Chastain hace de lobista despiadada peleando una ley de control de armas. La película se mueve como un ajedrez de estrategias dentro de Washington. El atractivo está en verla operar varios pasos adelante de todos.', 'El vocabulario legislativo y la cantidad de jugadas políticas simultáneas piden atención constante.', 'alta'),
  (594328, 'Le da por primera vez el protagonismo a Candace, la hermana secundaria de la serie original. Mantiene el humor absurdo y las canciones pegadizas que hicieron grande al show de Disney Channel. Para fans del programa es una fiesta; para quien nunca lo vio, es una comedia familiar más.', 'Si no viste la serie, varios chistes y guiños no te van a cerrar.', 'media'),
  (34204, 'Es la tercera de la saga de Disney Channel, con Marnie ya en la universidad de brujería en lugar de en el pueblo de sus abuelos. Mantiene el tono liviano de comedia familiar con algo de misterio, pensado para un público bastante chico. Sirve de puente entre las películas originales y el recast posterior.', 'Si viste las dos primeras, acá cambia la actriz que hace de Marnie y se nota la diferencia de tono.', 'fondo'),
  (48231, 'Cronenberg filma el quiebre entre Freud y Jung casi como un drama de cámara, apoyado en los diálogos y en la tensión entre sus protagonistas. Es cine de ideas antes que de acción, con el psicoanálisis naciente como campo de batalla.', 'Si vas buscando algo del Cronenberg más visceral de otras épocas, esta es mucho más contenida y hablada.', 'alta'),
  (777270, 'Branagh filma en blanco y negro su propia infancia en Belfast, con el conflicto norirlandés como ruido de fondo de la vida cotidiana. Judi Dench y Ciarán Hinds hacen de abuelos con una calidez que nunca cae en lo almibarado.', 'Si buscás que la violencia política ocupe el centro de la trama, acá queda siempre en segundo plano.', 'media'),
  (110415, 'Cada vagón del tren representa una clase social distinta, así que avanzar hacia la cabeza es escalar la pirámide. Bong Joon-ho mezcla violencia física cruda con sátira política sin bajarle el tono a ninguna de las dos.', 'La escena del aula en el vagón escolar es de las más extrañas que vas a ver en una película de acción.', 'alta'),
  (10158, 'Wesley Snipes y Woody Harrelson tienen una química de insultos y bravuconadas que sostiene la película más que cualquier partido de básquet. La relación entre los dos protagonistas es lo que sigue funcionando hoy, más que los chistes de época.', 'Varios chistes sobre raza y género quedaron anclados en su época.', 'media'),
  (376867, 'Cuenta la misma historia en tres edades del protagonista, con actores distintos en cada etapa, sin que se note el quiebre. La cámara se queda cerca de los cuerpos y los silencios, más que de los diálogos.', 'Si buscás una trama con conflicto externo marcado, te va a resultar lenta porque casi todo pasa adentro del personaje.', 'alta'),
  (646207, 'Liam Neeson maneja un camión quitanieves sobre hielo que se está quebrando, para rescatar mineros atrapados. Es una de esas películas de acción pura que no necesitan segunda lectura. El atractivo está en la tensión física del viaje, no en los personajes.', 'Los diálogos y las motivaciones de los personajes son de relleno, lo que importa es la road movie sobre el hielo.', 'media'),
  (1649, 'La secuela se anima a ir más lejos que la primera: pelean contra versiones robóticas de sí mismos. Después terminan jugando a las cartas contra la Muerte en persona, que se vuelve casi un personaje más.', 'Si no viste la primera, varios chistes sobre quiénes son estos dos pierden gracia.', 'fondo'),
  (157834, 'Christoph Waltz hace de un empleado corporativo que trabaja desde una capilla en ruinas. Ahí intenta resolver una ecuación que promete explicar el sentido de la existencia. Gilliam vuelve a su obsesión por la burocracia absurda, en un tono más melancólico que el de sus películas más conocidas.', 'El ritmo es lento y la trama avanza poco, más cerca del ensayo visual que de la historia con tensión.', 'alta'),
  (1151031, 'Los directores de Talk to Me vuelven con un terror que usa el ritual ocultista como excusa. De fondo habla del duelo y del abuso bajo la careta del cuidado. Sally Hawkins construye un personaje que inquieta mucho antes de que pase nada sobrenatural.', 'Tiene momentos de violencia física muy crudos, más cercanos al horror corporal que al terror sugerido.', 'alta'),
  (339846, 'Se ríe de lo ridículo del concepto original antes de que lo hagas vos. Dwayne Johnson y Zac Efron tienen buena química de comedia física entre ellos.', 'El humor es bastante subido de tono y grosero, así que no es tan familiar como sugiere el póster.', 'fondo'),
  (14444, 'Es la primera película de los Rugrats, con el conflicto clásico de hermano mayor celoso del bebé nuevo, llevado a una aventura en el bosque. Mantiene el humor de la serie, visto desde la perspectiva de los bebés que entienden todo mal. Ideal para quien creció con la serie o para ver con chicos chiquitos.', 'Si no conocés la serie, algunos personajes y chistes recurrentes no tienen la misma gracia.', 'fondo'),
  (302401, 'Oliver Stone arma el relato como un thriller de contrainteligencia, no como un documental sobre vigilancia masiva. Gordon-Levitt imita la voz y los gestos de Snowden de forma notable. La película alterna la fuga en Hong Kong con flashbacks de cómo un técnico leal al sistema termina filtrando todo.', 'Si ya viste el documental Citizenfour sobre el mismo tema, esta versión dramatizada agrega poco nuevo a los hechos.', 'alta'),
  (10897, 'Es una versión noventosa de los cortos clásicos de Our Gang, con el mismo humor de pandilla de barrio e infantil. El club anti chicas y el romance de Alfalfa dan la excusa para gags físicos simples. Funciona como comedia familiar liviana de los 90, sin más pretensión que esa.', 'El club anti chicas de los protagonistas se siente más incómodo que gracioso visto hoy.', 'fondo'),
  (320006, 'Jafar Panahi maneja un taxi real por Teherán con una cámara escondida, mientras tenía prohibido filmar por el gobierno iraní. Cada pasajero que sube abre una ventana distinta a la sociedad iraní, entre la censura y el humor cotidiano. Para quien le interesa el cine como acto político, más que por la trama en sí.', 'Si buscás una historia con arco narrativo clásico, el formato de viñetas sueltas no te va a cerrar.', 'media'),
  (146239, 'Vince Vaughn baja varios cambios respecto a sus comedias habituales, con un registro agridulce de tipo que no sabe qué hacer con la paternidad encima. La premisa absurda de los 533 hijos funciona más como excusa para hablar de responsabilidad que como chiste central.', 'El tramo del medio estira la misma situación sin sumar demasiado antes del cierre.', 'fondo'),
  (13313, 'Es la secuela directa a video de Disney, ubicada en algún momento entre las escenas de la película original. Suma personajes navideños nuevos a cambio de repetir la fórmula ya conocida del castillo encantado. Sirve como extra para fans chicos de la película original, no aporta mucho más.', 'La animación es notablemente más simple que la de la película original de 1991.', 'fondo'),
  (8068, 'Robert Rodriguez filma la venganza como un comic en movimiento, con poses y cámara lenta todo el tiempo. Antonio Banderas está ahí para verse genial, no para tener un arco de personaje complejo.', 'La trama es apenas una excusa para las escenas de acción.', 'fondo'),
  (50546, 'Es Adam Sandler en modo liviano, con Jennifer Aniston como contrapeso sensato a la mentira que arma el protagonista. La comedia sale más de la situación incómoda que armó él mismo que de chistes sueltos.', 'La premisa pide aceptar desde el arranque una mentira bastante forzada que sostiene toda la trama.', 'fondo'),
  (146216, 'Es más cómica y menos violenta que la primera, apoyada en el contraste entre espías veteranos y la energía de los más jóvenes. Helen Mirren con ametralladora sigue siendo el gancho principal de la saga.', 'Si te gustó la primera por el tono serio, esta se inclina bastante más hacia la comedia.', 'media'),
  (37472, 'Donnie Yen vuelve a hacer de Ip Man con la misma calma física de la primera. El conflicto con los ingleses le agrega una capa de orgullo nacional a las peleas de Wing Chun. Sammo Hung como rival le da a las coreografías un peso distinto.', 'Si no viste la primera, parte del peso del personaje de Ip Man como maestro se pierde.', 'media'),
  (6520, 'Sean Connery hace de Arturo como un rey razonable y melancólico, no el mito heroico de siempre. Eso corre el foco del triángulo amoroso hacia su punto de vista, más que hacia Lanzarote.', 'Las escenas de batalla son genéricas y se sienten puestas para justificar el presupuesto.', 'media'),
  (227738, 'Es la versión animada de los personajes de Ibáñez, con el humor de gags visuales y chistes de doble sentido típico del cómic español. Funciona mejor para quien ya conoce a los personajes que para quien los descubre por primera vez.', 'Si no te criaste con el cómic de Mortadelo y Filemón, varios chistes y referencias no te van a cerrar.', 'fondo'),
  (37094, 'Michael Douglas atraviesa Los Ángeles a pie y de traje, y cada parada se convierte en una pequeña explosión distinta. Nunca queda claro si es una crítica social o el retrato de un tipo que perdió la cabeza. Es incómoda a propósito, no por accidente.', 'El personaje puede leerse hoy como la defensa de la furia de un hombre blanco frustrado, algo que incomoda más que en los 90.', 'alta'),
  (72570, 'Está basada en un caso real, pero juega todas sus cartas a la pregunta de si se puede reconstruir un amor con alguien que ya no te recuerda. Channing Tatum hace de paciencia, no de galán de acción.', 'El ritmo es lento y bastante previsible en la segunda mitad.', 'fondo'),
  (1729, 'Jackie Chan y Jet Li comparten pantalla por primera vez en una aventura de kung fu. Mezcla mitología china con un pibe de Boston transportado en el tiempo. El plato fuerte es verlos pelear juntos, más que la trama en sí.', 'La historia del chico moderno transportado es bastante genérica, funciona como excusa para llegar a las peleas.', 'media'),
  (280, 'Las escenas de acción se apoyan en efectos prácticos y animatronics, no en CGI pesado, y por eso envejecieron mejor que otras de su época. El vínculo entre Sarah Connor y el T-800 le da peso emocional a la persecución. El T-1000 funciona como villano sin necesitar casi diálogo.', 'Si ya la viste varias veces, las frases y escenas te van a resultar demasiado conocidas como para sorprenderte.', 'media'),
  (19184, 'Es la ópera prima de Luc Besson, filmada sin un solo diálogo porque en esta historia la gente perdió la capacidad de hablar. Es blanco y negro, mundo postnuclear, con una estética más cercana al cine experimental que a la ciencia ficción de acción. Si te gusta el cine que arriesga en la forma antes que en la trama, la vas a disfrutar.', 'Si necesitás diálogos para seguir una historia, esta película no te da ninguno: es completamente muda.', 'alta'),
  (21299, 'Es la película más de supervivencia de la saga Benji: casi no hay personas, solo un perro y los cachorros de puma contra el monte. Joe Camp filmó todo con animales reales, sin trucos de animación, así que la tensión en las persecuciones se siente genuina. Funciona bien para ver con chicos que ya conocen a Benji y buscan más aventura que comedia.', 'Si esperás diálogos y personajes humanos fuertes, la vas a extrañar: casi toda la película es el perro solo con los cachorros.', 'fondo'),
  (4499, 'Es la primera película de Almodóvar, filmada con poco presupuesto en plena Movida madrileña. Ya se nota su gusto por personajes al límite y humor incorrecto, más crudo que en sus películas posteriores.', 'Si esperás la prolijidad visual de sus películas posteriores, la factura casera y el ritmo irregular te van a descolocar.', 'media'),
  (17006, 'Es una parodia directa del blaxploitation de los setenta, con Keenen Ivory Wayans burlándose de los códigos del género. El humor es de chiste visual y exageración, no de ironía sutil.', 'Si no conocés las películas blaxploitation originales, buena parte de los chistes por referencia se te van a pasar de largo.', 'media'),
  (25199, 'Es una comedia adolescente ochentera que se volvió de culto más por sus escenas ridículas de rap y baile que por la trama de brujería. Se disfruta mejor sabiendo que el encanto está en lo involuntariamente gracioso.', 'Si la ves esperando una comedia prolija, los números musicales van a parecerte más raros que graciosos.', 'fondo'),
  (39256, 'Es el reestreno norteamericano de la película japonesa de 1984, con escenas nuevas de Raymond Burr insertadas para el público de Estados Unidos. Vuelve al tono serio y nuclear de las primeras películas, lejos de los monstruos amistosos de los sesenta y setenta.', 'Si viste la versión japonesa original, las escenas agregadas con Burr se notan pegadas y cortan el ritmo.', 'media'),
  (874299, 'Es un especial fuera de temporada que imagina a Stan, Kyle, Cartman y Kenny ya adultos, años después de la pandemia. El tono es mucho más oscuro que el de la serie habitual, como una fábula sobre cómo esos años cambiaron a una generación. Conviene conocer a los personajes de la serie para que el contraste con su versión adulta tenga peso.', 'Si no seguís South Park, el peso emocional de ver a los personajes envejecidos no te va a pegar igual.', 'media'),
  (704854, 'Es un documental de National Geographic sobre uno de los grandes misterios del montañismo. Busca pistas sobre si Mallory e Irvine llegaron a la cima del Everest en 1924, treinta años antes que Hillary. Sigue a alpinistas actuales que rastrean el cuerpo desaparecido de Irvine en busca de la cámara que podría probarlo.', 'El misterio central sigue sin resolverse hoy, así que no esperes una respuesta definitiva.', 'media'),
  (652004, 'Jim Cummings dirige y protagoniza esta mezcla de comedia nerviosa y terror de pueblo chico, con muertes que podrían ser de un hombre lobo. Su personaje está más preocupado por no perder la cabeza y por su padre enfermo que por el supuesto monstruo. Funciona para quien banca el humor incómodo metido dentro de una historia de terror.', 'El tono salta entre comedia y terror de forma abrupta, puede desorientar si esperás un slasher clásico.', 'media'),
  (991833, 'Es un especial que cruza a los perros de PAW Patrol con un grupo nuevo de gatos héroes, pensado como evento puntual. Mantiene la fórmula de misiones simultáneas que ya conocen los chicos que siguen la serie.', 'Si tu hija o hijo no conoce la serie, el cruce con la Cuadrilla Cat no se explica demasiado por sí solo.', 'fondo'),
  (659067, 'Es un thriller francés de Netflix sobre un aserradero en medio del bosque que termina en guerra con un cartel de drogas. Tiene más acción directa y violencia que trama, con ritmo rápido y pocas vueltas. No busca profundidad, busca tensión constante.', 'Si buscás algo más que acción pura, la trama de fondo es bastante simple y predecible.', 'media'),
  (59387, 'Cuenta el origen de las tres antes de que Townsville las conociera como heroínas, algo que la serie nunca se había detenido a mostrar. Mantiene el humor y la estética pop del programa, con una trama algo más oscura en el tramo final. Para fans del show o chicos que ya conocen a los personajes.', 'Si nunca viste la serie, el tono entre tierno y violento del final desconcierta.', 'media'),
  (1072371, 'Ben Kingsley hace de un hombre mayor con problemas de memoria que encuentra un alienígena asustado en su patio. Decide cuidarlo casi como a una mascota, y la película usa eso para hablar de la vejez y la soledad. El alienígena casi no habla, así que el peso actoral cae en Kingsley y en el grupo de vecinos que se suman.', 'Si esperás ciencia ficción con acción, esta película es mucho más chica y lenta de lo que sugiere la premisa.', 'media'),
  (62527, 'Es la secuela de ''Johnny Tsunami'', un clásico menor de Disney Channel, y repite la fórmula del choque cultural, con el surf hawaiano como escenario. Está pensada para pasar el rato en familia, sin pretender mucho más que eso.', 'Si no viste la primera, algunos vínculos entre personajes te van a costar un poco más seguirlos.', 'fondo'),
  (1401905, 'Es el documental de Netflix sobre Bryan Johnson, el millonario que gasta su fortuna en un protocolo extremo antienvejecimiento. Funciona como retrato de una obsesión más que como informe médico neutral, y deja ver también lo incómodo del personaje. Interesa tanto a quien sigue el tema de la longevidad como a quien quiere ver un estudio de ego.', 'Si esperás un análisis científico equilibrado, el documental está más del lado del personaje que de una mirada crítica externa.', 'media'),
  (7552, 'Jim Carrey hace de ejecutivo que de la noche a la mañana pierde todo por un afano corporativo tipo Enron. La gracia está en verlo a él y a Leslie Mann probar changas absurdas para no perder la casa. Es comedia física, liviana, sin pretensión de crítica social real.', 'Si buscás algo con más filo o crítica real al mundo corporativo, esta se queda corta.', 'fondo'),
  (916053, 'Es una comedia romántica de Amazon con la premisa clásica del anillo equivocado. La protagonista recibe por error el compromiso que su novio compró para otra mujer, y ahí se cruzan dos parejas. Sirve para una tarde sin pretensiones, con el formato de siempre del género.', 'Si ya viste muchas comedias románticas de parejas que se cruzan por un malentendido, el desarrollo no te va a sorprender.', 'media'),
  (26518, 'Kelly Reichardt filma a dos amigos que ya no tienen mucho que decirse en un fin de semana de montaña. Los silencios pesan más que los diálogos, en un cine de observación sin conflicto explícito.', 'Si necesitás que pase algo, el ritmo contemplativo y la falta de trama te va a aburrir.', 'media'),
  (517302, 'Es la película finlandesa conocida como Hatching, sobre una gimnasta adolescente que esconde un huevo extraño. Lo hace mientras intenta cumplir con las exigencias de una madre asfixiante, obsesionada con mostrar una familia perfecta. El terror acá funciona como metáfora de la presión familiar, más incómoda que aterradora.', 'Si buscás terror de sustos, esta película hace otra cosa: la tensión viene de la relación materno-filial, no de la criatura.', 'alta'),
  (13676, 'Es la precuela directa a video que explica por qué la música estaba prohibida en el reino de Tritón, antes de la película original. Apunta de lleno al público infantil que ya conoce a Ariel y sus hermanas. No agrega mucho si ya viste la película de 1989.', 'La animación y las canciones no llegan al nivel de la película original de 1989.', 'fondo'),
  (4141, 'Clive Owen rescata a un bebé en medio de un tiroteo y de ahí no para de pelear por él durante toda la película. Es acción exagerada a propósito, con escenas imposibles filmadas como chiste visual recurrente. Paul Giamatti hace de villano con gracia, casi robándole la película al protagonista.', 'Si tomás la acción en serio o te molesta la violencia absurda, esta no es para vos.', 'media'),
  (4552, 'Kim Jee-woon construye el terror a partir de lo que no se entiende bien de la relación entre las hermanas y la madrastra. La película se puede ver dos veces y cambia de sentido en la segunda.', 'La estructura narrativa es deliberadamente confusa y pide atención total para que el final cierre.', 'alta'),
  (4547, 'Fincher encierra casi toda la película en una casa y mueve la cámara por paredes y pisos como si la casa fuera un personaje más. La tensión viene de la logística, de quién controla qué parte de la casa en cada momento.', 'Si ya viste varias películas de intrusos en casa, la estructura te va a resultar familiar.', 'alta'),
  (615665, 'Emma Roberts y Luke Bracey arrancan juntándose en cada feriado del año solo para no ir solos a los eventos familiares. No hay compromiso romántico de por medio, al menos al principio. Es una comedia liviana que recorre casi todas las fiestas del calendario gringo.', 'El humor es bastante más subido de tono que el de una comedia romántica de fiestas típica.', 'fondo'),
  (10719, 'Will Ferrell juega al elfo adulto sin un gramo de ironía. Ese choque entre su inocencia y el cinismo de Nueva York es la base de la comedia. Es de esas navideñas que gustan incluso a quien no es fan de la época.', 'El humor es bastante infantil y repetitivo en el tramo de Nueva York.', 'fondo'),
  (9476, 'Mezcla justas medievales con banda de rock y anacronismos a propósito, como el público cantando en las gradas. Heath Ledger joven lidera un grupo con buena onda entre sí.', 'Si esperás precisión histórica, los anacronismos constantes te van a sacar de la película.', 'fondo')
) as v(tmdb_id, razon, advertencia, atencion)
where rt.tmdb_id = v.tmdb_id and rt.media_type = 'movie' and rt.razon is null;

